import re
import os


def task_func(request):
    def response(status, message=""):
        return f"HTTP/1.1 {status}\r\n\r\n{message}"

    if not isinstance(request, str) or not request:
        return response("400 Bad Request", "Invalid request")

    request_line = request.splitlines()[0] if request.splitlines() else ""
    match = re.fullmatch(r"GET\s+(\S+)\s+HTTP/1\.[01]", request_line)
    if not match:
        return response("400 Bad Request", "Invalid HTTP GET request")

    target = match.group(1)

    try:
        from urllib.parse import unquote, urlsplit

        parsed = urlsplit(target)
        if parsed.scheme or parsed.netloc:
            return response("400 Bad Request", "Invalid path")
        path = unquote(parsed.path)
    except Exception:
        return response("400 Bad Request", "Invalid path")

    if not path or path == "/" or "\x00" in path:
        return response("400 Bad Request", "Invalid filename")

    path = path.replace("\\", "/")
    parts = path.split("/")
    if ".." in parts:
        return response("400 Bad Request", "Invalid filename")

    filename = path.lstrip("/")
    base_dir = os.path.realpath(os.getcwd())
    file_path = os.path.realpath(os.path.join(base_dir, filename))

    try:
        if os.path.commonpath((base_dir, file_path)) != base_dir:
            return response("400 Bad Request", "Invalid filename")

        if not os.path.isfile(file_path):
            return response("404 Not Found", "File not found")

        with open(file_path, "rb") as file:
            content_bytes = file.read()

        content = content_bytes.decode("utf-8")
    except (OSError, UnicodeDecodeError):
        return response("404 Not Found", "File not found")

    return (
        "HTTP/1.1 200 OK\r\n"
        f"Content-Length: {len(content_bytes)}\r\n"
        "\r\n"
        f"{content}"
    )

