        raise ValueError("All predictor columns must be numeric")

    if not pd.api.types.is_numeric_dtype(y.dtype):
        raise ValueError("Target column must be numeric")

    if df.isna().any().any():
        raise ValueError("DataFrame must not contain missing values")

    if df.select_dtypes(include="number").isin([float("inf"), float("-inf")]).any().any():
        raise ValueError("DataFrame must not contain infinite values")

    model = LinearRegression()
    model.fit(X, y)

    return float(model.score(X, y))

