import pandas as pd
import seaborn as sns
import numpy as np
import ast


def task_func(csv_file):
    required_columns = ["email", "list"]
    output_columns = ["email", "list", "sum", "mean", "std"]

    try:
        data = pd.read_csv(csv_file)
    except pd.errors.EmptyDataError:
        data = pd.DataFrame(columns=required_columns)

    missing_columns = [column for column in required_columns if column not in data.columns]
    if missing_columns:
        raise ValueError(f"Missing required columns: {missing_columns}")

    records = []

    for row_number, row in data.iterrows():
        email = row["email"]
        raw_list = row["list"]

        if pd.isna(email):
            raise ValueError(f"Missing email at row {row_number}")

        try:
            values = ast.literal_eval(raw_list) if isinstance(raw_list, str) else raw_list
        except (SyntaxError, ValueError) as exc:
            raise ValueError(
                f"Malformed list at row {row_number}: {raw_list!r}"
            ) from exc

        if not isinstance(values, (list, tuple, np.ndarray)):
            raise ValueError(
                f"Expected a list at row {row_number}, got {type(values).__name__}"
            )

        values = list(values)

        for value in values:
            if isinstance(value, (bool, np.bool_)) or not isinstance(
                value, (int, float, np.integer, np.floating)
            ):
                raise ValueError(f"Non-numeric value at row {row_number}: {value!r}")
            if not np.isfinite(value):
                raise ValueError(
                    f"Missing or non-finite value at row {row_number}: {value!r}"
                )

        records.append(
            {
                "email": email,
                "list": values,
                "sum": sum(values),
                "mean": np.mean(values) if values else np.nan,
                "std": np.std(values, ddof=0) if values else np.nan,
            }
        )

    df = pd.DataFrame(records, columns=output_columns)
    ax = sns.histplot(data=df, x="mean")

    return df, ax

