import pandas as pd
import numpy as np
import itertools
from datetime import datetime, timedelta
import seaborn as sns


def task_func(df, fruits=None, days=None, seed=None, sales_lower_bound=1, sales_upper_bound=50):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("'df' must be a pandas DataFrame")

    if not df.empty:
        raise ValueError("'df' must be empty")

    if sales_lower_bound >= sales_upper_bound:
        raise ValueError(
            "'sales_lower_bound' must be less than 'sales_upper_bound'"
        )

    if fruits is None:
        fruits = ["Apple", "Banana", "Orange"]

    if days is None:
        days = 7

    if days < 0:
        raise ValueError("'days' must not be negative")

    start_date = datetime.now()
    combinations = list(itertools.product(fruits, range(days)))

    rng = np.random.default_rng(seed)
    sales = rng.integers(
        sales_lower_bound,
        sales_upper_bound + 1,
        size=len(combinations),
    )

    records = [
        {
            "fruit": fruit,
            "date": start_date + timedelta(days=day_offset),
            "sales": int(sale),
        }
        for (fruit, day_offset), sale in zip(combinations, sales)
    ]

    generated_df = pd.DataFrame(records, columns=["fruit", "date", "sales"])
    updated_df = pd.concat([df.copy(), generated_df], ignore_index=True)

    plot = sns.catplot(
        data=updated_df,
        x="fruit",
        y="sales",
        kind="box",
    )

    return updated_df, plot

