from datetime import datetime
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt


def task_func(start_time, end_time, step, trend, seed=42):
    try:
        start = pd.Timestamp(start_time)
        end = pd.Timestamp(end_time)
    except Exception as exc:
        raise ValueError("Invalid start_time or end_time") from exc

    if pd.isna(start) or pd.isna(end):
        raise ValueError("start_time and end_time must be valid timestamps")

    if start > end:
        raise ValueError("start_time must not be later than end_time")

    try:
        offset = pd.tseries.frequencies.to_offset(step)
    except Exception as exc:
        raise ValueError("Invalid step") from exc

    try:
        if start + offset <= start:
            raise ValueError("step must be positive")
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError("step must be a valid positive frequency") from exc

    if start == end:
        timestamps = pd.DatetimeIndex([start])
    else:
        timestamps = pd.date_range(start=start, end=end, freq=offset)

    try:
        trend = float(trend)
    except (TypeError, ValueError) as exc:
        raise ValueError("trend must be numeric") from exc

    if not np.isfinite(trend):
        raise ValueError("trend must be finite")

    rng = np.random.default_rng(seed)
    noise = rng.normal(size=len(timestamps))
    values = noise + np.arange(len(timestamps)) * trend

    _, ax = plt.subplots()
    ax.plot(timestamps, values)
    ax.set_xlabel("Time")
    ax.set_ylabel("Value")

    return ax

