import numpy as np
from sklearn import datasets
from sklearn.model_selection import train_test_split
from sklearn.linear_model import LinearRegression


def task_func(n_samples=100, n_features=10, random_seed=None):
    if isinstance(n_samples, bool) or not isinstance(n_samples, (int, np.integer)):
        raise TypeError("n_samples must be an integer")
    if isinstance(n_features, bool) or not isinstance(n_features, (int, np.integer)):
        raise TypeError("n_features must be an integer")
    if n_samples < 2:
        raise ValueError("n_samples must be at least 2")
    if n_features < 1:
        raise ValueError("n_features must be positive")
    if isinstance(random_seed, bool) or (
        random_seed is not None
        and not isinstance(random_seed, (int, np.integer))
    ):
        raise TypeError("random_seed must be an integer or None")

    X, y = datasets.make_regression(
        n_samples=int(n_samples),
        n_features=int(n_features),
        random_state=random_seed,
    )

    X_train, X_test, y_train, y_test = train_test_split(
        X, y, test_size=0.2, random_state=random_seed
    )

    model = LinearRegression()
    model.fit(X_train, y_train)

    predictions = model.predict(X_test)
    mse = float(np.mean((y_test - predictions) ** 2))

    return (
        predictions,
        np.asarray(model.coef_),
        float(model.intercept_),
        mse,
    )

