import re
from urllib.parse import urlparse
from bs4 import BeautifulSoup
import requests


def task_func(myString):
    no_url_message = "No valid URL found in the provided string."

    if not isinstance(myString, str):
        return no_url_message

    candidates = re.findall(r"https?://[^\s<>\"']+", myString, re.IGNORECASE)
    url = None

    for candidate in candidates:
        candidate = candidate.rstrip(".,!?;:]}")

        while candidate.endswith(")") and candidate.count(")") > candidate.count("("):
            candidate = candidate[:-1]

        parsed = urlparse(candidate)

        try:
            hostname = parsed.hostname
            parsed.port
        except ValueError:
            continue

        if parsed.scheme.lower() in {"http", "https"} and hostname:
            url = candidate
            break

    if url is None:
        return no_url_message

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException:
        return f"Unable to fetch the content of the URL: {url}"

    soup = BeautifulSoup(response.content, "html.parser")
    title_tag = soup.find("title")

    if title_tag is None:
        return "No title tag found in the webpage."

    title = title_tag.get_text(strip=True)
    return title if title else "No title tag found in the webpage."

