import csv
from collections import Counter
import pandas as pd
import matplotlib.pyplot as plt


def task_func(file_path):
    """Identify duplicate rows in a CSV file and plot their counts."""
    if isinstance(file_path, str):
        path = file_path
    elif hasattr(file_path, "__fspath__"):
        path = str(file_path.__fspath__())
    else:
        raise ValueError("file_path must be a valid path")

    if not path.lower().endswith(".csv"):
        raise ValueError("file_path must have a .csv extension")

    rows = []
    try:
        with open(path, "r", encoding="utf-8", newline="") as csv_file:
            reader = csv.reader(csv_file, strict=True)
            rows = [tuple(row) for row in reader]
    except (csv.Error, UnicodeError) as exc:
        raise ValueError("Invalid CSV format") from exc

    if rows:
        column_count = len(rows[0])
        if any(len(row) != column_count for row in rows):
            raise ValueError("CSV rows have inconsistent column counts")

    counts = Counter(rows)
    duplicates = {
        row: count for row, count in counts.items() if count > 1
    }

    duplicate_dataframe = pd.DataFrame(
        {
            "row": [", ".join(row) for row in duplicates],
            "count": list(duplicates.values()),
        }
    )

    figure, ax = plt.subplots(figsize=(8, 5))

    if not duplicate_dataframe.empty:
        duplicate_dataframe.plot(
            kind="bar",
            x="row",
            y="count",
            ax=ax,
            legend=False,
        )
        ax.tick_params(axis="x", rotation=45)

    ax.set_title("Duplicate CSV Rows")
    ax.set_xlabel("Duplicate rows")
    ax.set_ylabel("Count")
    figure.tight_layout()

    return duplicates, ax

