import seaborn as sns
from scipy.stats import chi2_contingency
import pandas as pd


def task_func(df1, df2, column1="feature1", column2="feature2"):
    if "id" not in df1.columns:
        raise KeyError("df1 must contain an 'id' column")
    if "id" not in df2.columns:
        raise KeyError("df2 must contain an 'id' column")

    merged = df1.merge(
        df2,
        on="id",
        how="inner",
        suffixes=("_df1", "_df2"),
    )

    missing = [
        column
        for column in (column1, column2)
        if column not in merged.columns
    ]
    if missing:
        raise KeyError(f"Missing column(s): {', '.join(missing)}")

    contingency = pd.crosstab(
        merged[column1],
        merged[column2],
    )

    if contingency.empty:
        raise ValueError("The contingency table is empty")

    try:
        _, p_value, _, _ = chi2_contingency(contingency)
    except ValueError as exc:
        raise ValueError(
            "The contingency table is degenerate"
        ) from exc

    heatmap = sns.heatmap(contingency)

    return float(p_value), heatmap

