import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not process_name or not process_name.strip():
        return 0

    current_pid = os.getpid()
    pids = set()

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                check=False,
            )
            if result.returncode != 0:
                return 0

            for line in result.stdout.splitlines():
                fields = [field.strip().strip('"') for field in line.split(",")]
                if len(fields) < 2 or fields[0] != process_name:
                    continue
                try:
                    pid = int(fields[1])
                except ValueError:
                    continue
                if pid != current_pid:
                    pids.add(pid)
        else:
            result = subprocess.run(
                ["ps", "-A", "-o", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )
            if result.returncode != 0:
                return 0

            for line in result.stdout.splitlines():
                parts = line.strip().split(None, 1)
                if len(parts) != 2 or parts[1] != process_name:
                    continue
                try:
                    pid = int(parts[0])
                except ValueError:
                    continue
                if pid != current_pid:
                    pids.add(pid)
    except (OSError, subprocess.SubprocessError):
        return 0

    stopped = 0

    for pid in pids:
        try:
            if os.name == "nt":
                result = subprocess.run(
                    ["taskkill", "/PID", str(pid), "/F"],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                if result.returncode == 0:
                    stopped += 1
            else:
                os.kill(pid, signal.SIGTERM)
                stopped += 1
        except (OSError, subprocess.SubprocessError):
            continue

    if stopped:
        time.sleep(1)

    return stopped

