import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    return "/fake/backup/path"


def task_func(directory):
    errors = []
    backup_directory = get_unique_backup_dir()

    if not os.path.isdir(directory):
        if os.path.exists(directory):
            errors.append(f"Source path is not a directory: {directory}")
        else:
            errors.append(f"Source directory does not exist: {directory}")
        return backup_directory, errors

    source_real = os.path.realpath(directory)
    backup_real = os.path.realpath(backup_directory)

    try:
        common_path = os.path.commonpath((source_real, backup_real))
        if common_path in (source_real, backup_real):
            errors.append(
                "Source and backup directories must not contain one another"
            )
            return backup_directory, errors
    except ValueError as error:
        errors.append(f"Could not compare source and backup paths: {error}")
        return backup_directory, errors

    if os.path.lexists(backup_directory):
        errors.append(f"Backup directory already exists: {backup_directory}")
        return backup_directory, errors

    try:
        os.makedirs(backup_directory)
    except OSError as error:
        errors.append(f"Could not create backup directory: {error}")
        return backup_directory, errors

    def copy_and_clean(source_path, target_path):
        try:
            if os.path.islink(source_path):
                os.symlink(os.readlink(source_path), target_path)
                os.unlink(source_path)
                return True

            if os.path.isdir(source_path):
                os.makedirs(target_path)
                successful = True

                try:
                    names = os.listdir(source_path)
                except OSError as error:
                    errors.append(f"Could not list directory {source_path}: {error}")
                    return False

                for name in names:
                    child_source = os.path.join(source_path, name)
                    child_target = os.path.join(target_path, name)
                    if not copy_and_clean(child_source, child_target):
                        successful = False

                if successful:
                    try:
                        shutil.copystat(source_path, target_path)
                        os.rmdir(source_path)
                    except OSError as error:
                        errors.append(
                            f"Could not remove directory {source_path}: {error}"
                        )
                        successful = False

                return successful

            shutil.copy2(source_path, target_path)
            os.unlink(source_path)
            return True

        except (OSError, shutil.Error) as error:
            errors.append(f"Could not process {source_path}: {error}")
            return False

    try:
        for name in os.listdir(directory):
            source_path = os.path.join(directory, name)
            target_path = os.path.join(backup_directory, name)
            copy_and_clean(source_path, target_path)
    except OSError as error:
        errors.append(f"Could not read source directory: {error}")

    return backup_directory, errors

