        raise ValueError("MIN_WORDS must not exceed MAX_WORDS")

    if isinstance(WORDS_POOL, (str, bytes)):
        raise TypeError("WORDS_POOL must be a collection of words")

    try:
        pool = tuple(WORDS_POOL)
    except TypeError as exc:
        raise TypeError("WORDS_POOL must be iterable") from exc

    if MAX_WORDS > 0 and not pool:
        raise ValueError("WORDS_POOL must not be empty")
    if any(not isinstance(word, str) for word in pool):
        raise TypeError("WORDS_POOL must contain only strings")

