from glob import glob


def task_func(src_folder, dst_folder):
    if not isinstance(src_folder, (str, os.PathLike)) or not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": "Source folder does not exist or is not a directory.",
            "failed_files": [],
        }

    if not isinstance(dst_folder, (str, os.PathLike)):
        return {
            "success": False,
            "message": "Destination folder path is invalid.",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
        if not os.path.isdir(dst_folder):
            raise OSError("Destination path is not a directory.")
    except (OSError, TypeError) as exc:
        return {
            "success": False,
            "message": f"Could not create destination folder: {exc}",
            "failed_files": [],
        }

    try:
        files = [
            entry.path
            for entry in os.scandir(src_folder)
            if entry.is_file(follow_symlinks=False)
        ]
    except OSError as exc:
        return {
            "success": False,
            "message": f"Could not read source folder: {exc}",
            "failed_files": [],
        }

    if not files:
        return {
            "success": True,
            "message": "No files were found in the source folder.",
            "failed_files": [],
        }

    failed_files = []
    processes = []

    for file_path in files:
        filename = os.path.basename(file_path)
        try:
            process = subprocess.Popen(["gzip", file_path], shell=False)
            processes.append((filename, file_path, process))
        except (OSError, subprocess.SubprocessError):
            failed_files.append(filename)

    compressed_files = []

    for filename, file_path, process in processes:
        try:
            return_code = process.wait()
        except (OSError, subprocess.SubprocessError):
            return_code = 1

        if return_code == 0:
            compressed_files.append((filename, file_path + ".gz"))
        else:
            failed_files.append(filename)

    source_real = os.path.realpath(src_folder)
    destination_real = os.path.realpath(dst_folder)

    for filename, compressed_path in compressed_files:
        destination_path = os.path.join(
            dst_folder,
            os.path.basename(compressed_path),
        )

        try:
            if source_real != destination_real:
                shutil.move(compressed_path, destination_path)
        except (OSError, shutil.Error):
            failed_files.append(filename)

    if failed_files:
        return {
            "success": False,
            "message": f"{len(failed_files)} file(s) failed to compress or move.",
            "failed_files": failed_files,
        }

    return {
        "success": True,
        "message": f"Successfully compressed and moved {len(files)} file(s).",
        "failed_files": [],
    }

