import json
import re
import pandas as pd


def task_func(json_str):
    number_pattern = re.compile(
        r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?"
    )

    def double_numbers_in_string(value):
        def replace(match):
            return str(float(match.group()) * 2)

        return number_pattern.sub(replace, value)

    def normalize_value(value):
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return float(value * 2)
        if isinstance(value, list):
            return [normalize_value(item) for item in value]
        if isinstance(value, str):
            return double_numbers_in_string(value)
        return value

    try:
        data = json.loads(json_str)
    except (TypeError, ValueError, RecursionError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    try:
        normalized = {
            key: normalize_value(value)
            for key, value in data.items()
        }

        list_values = [
            value for value in normalized.values()
            if isinstance(value, list)
        ]

        if not list_values:
            normalized = {
                key: [value]
                for key, value in normalized.items()
            }
        else:
            lengths = [len(value) for value in list_values]
            if len(set(lengths)) > 1:
                return pd.DataFrame()

            row_count = lengths[0]
            normalized = {
                key: value if isinstance(value, list)
                else [value] * row_count
                for key, value in normalized.items()
            }

        return pd.DataFrame(normalized)
    except (TypeError, ValueError, OverflowError, RecursionError):
        return pd.DataFrame()

