def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    def read_file(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8', newline='') as file:
                lines = file.readlines()
        except FileNotFoundError:
            raise
        except Exception as exc:
            raise Exception(f"Error reading file: {file_path}") from exc

        if not lines:
            raise ValueError(f"File is empty: {file_path}")

        try:
            list(csv.reader(lines, delimiter=delimiter, quotechar=quotechar))
        except Exception as exc:
            raise Exception(f"Error parsing CSV file: {file_path}") from exc

        return lines

    def strip_line_ending(line):
        return line.rstrip('\r\n')

    lines1 = [strip_line_ending(line) for line in read_file(file_path1)]
    lines2 = [strip_line_ending(line) for line in read_file(file_path2)]

    differences = []
    line_number1 = 1
    line_number2 = 1

    for diff_line in ndiff(lines1, lines2):
        status = diff_line[0]
        content = diff_line[2:]

        if status == ' ':
            differences.append({
                'Line Number': line_number1,
                'Status': ' ',
                'Content': content
            })
            line_number1 += 1
            line_number2 += 1
        elif status == '-':
            differences.append({
                'Line Number': line_number1,
                'Status': '-',
                'Content': content
            })
            line_number1 += 1
        elif status == '+':
            differences.append({
                'Line Number': line_number2,
                'Status': '+',
                'Content': content
            })
            line_number2 += 1

    return pd.DataFrame(
        differences,
        columns=['Line Number', 'Status', 'Content']
    )

