        name = str(column).lower()
        if name == "id":
            return 0
        if name.endswith("_id") or name.endswith("id"):
            return 1
        return 2

    merge_column = min(common_columns, key=id_priority)

    merged = df1[[merge_column, column1]].merge(
        df2[[merge_column, column2]],
        on=merge_column,
        how="inner",
    )

