import os
import hashlib
import json
from pathlib import Path


def task_func(directory: str) -> str:
    base_dir = Path(os.path.abspath(directory))

    if not base_dir.exists():
        raise FileNotFoundError(f"Directory does not exist: {directory}")
    if not base_dir.is_dir():
        raise NotADirectoryError(f"Path is not a directory: {directory}")

    output_path = base_dir / "hashes.json"
    hashes = {}

    for root, _, files in os.walk(base_dir, followlinks=False):
        for filename in files:
            file_path = Path(root) / filename

            if file_path == output_path or not file_path.is_file():
                continue

            digest = hashlib.sha256()
            with file_path.open("rb") as file:
                for chunk in iter(lambda: file.read(1024 * 1024), b""):
                    digest.update(chunk)

            relative_path = file_path.relative_to(base_dir).as_posix()
            hashes[relative_path] = digest.hexdigest()

    with output_path.open("w", encoding="utf-8") as file:
        json.dump(hashes, file, ensure_ascii=False, indent=2, sort_keys=True)
        file.write("\n")

    return str(output_path)

