import zipfile
import os
import re
import shutil


def task_func(source_dir: str, target_dir: str, archive_name: str = "archive.zip") -> str:
    if not os.path.isdir(source_dir):
        raise ValueError(f"Source directory does not exist: {source_dir}")

    if (
        not archive_name
        or os.path.basename(archive_name) != archive_name
        or archive_name in {".", ".."}
    ):
        raise ValueError("archive_name must be a simple filename")

    os.makedirs(target_dir, exist_ok=True)

    archive_path = os.path.abspath(os.path.join(target_dir, archive_name))
    processed_pattern = re.compile(r"_processed(?:\.[^.]+)*$")

    files_to_archive = []
    for entry in os.listdir(source_dir):
        file_path = os.path.join(source_dir, entry)
        if (
            os.path.isfile(file_path)
            and processed_pattern.search(entry)
            and os.path.abspath(file_path) != archive_path
        ):
            files_to_archive.append(file_path)

    with zipfile.ZipFile(
        archive_path,
        mode="w",
        compression=zipfile.ZIP_DEFLATED,
    ) as archive:
        for file_path in sorted(files_to_archive):
            archive.write(file_path, arcname=os.path.basename(file_path))

    return archive_path

