from scipy.stats import norm


def task_func(df, column, bins=30, density=True, alpha=0.6, color="g", seed=None):
    if column not in df.columns:
        raise KeyError(f"Column {column!r} was not found in the DataFrame.")

    if not isinstance(density, (bool, np.bool_)):
        raise TypeError("density must be a boolean.")

    if isinstance(alpha, (bool, np.bool_)) or not isinstance(
        alpha, (int, float, np.integer, np.floating)
    ):
        raise TypeError("alpha must be a real number.")
    if not np.isfinite(alpha) or not 0 <= alpha <= 1:
        raise ValueError("alpha must be a finite number between 0 and 1.")

    if isinstance(bins, (bool, np.bool_)):
        raise TypeError("bins must be a positive integer, string, or bin-edge sequence.")
    if isinstance(bins, (int, np.integer)) and bins <= 0:
        raise ValueError("bins must be a positive integer.")

    series = df[column].dropna()
    if series.empty:
        raise ValueError("The selected column contains no valid observations.")

    dtype_kind = getattr(series.dtype, "kind", None)
    if dtype_kind not in "iuf":
        raise TypeError("The selected column must contain numeric data.")

    try:
        data = np.asarray(series.to_numpy(), dtype=float)
    except (TypeError, ValueError) as exc:
        raise TypeError("The selected column must contain numeric data.") from exc

    if data.size < 2:
        raise ValueError("At least two valid observations are required.")
    if not np.all(np.isfinite(data)):
        raise ValueError("The data must contain only finite numeric values.")
    if np.all(data == data[0]):
        raise ValueError("A normal distribution cannot be fitted to constant data.")

    fig, ax = plt.subplots()
    _, edges, _ = ax.hist(
        data,
        bins=bins,
        density=density,
        alpha=alpha,
        color=color,
    )

    mean = np.mean(data)
    std = np.std(data, ddof=1)
    x = np.linspace(np.min(data), np.max(data), 200)
    pdf = norm.pdf(x, loc=mean, scale=std)

    if density:
        curve = pdf
    else:
        bin_width = float(np.mean(np.diff(edges)))
        curve = pdf * data.size * bin_width

    ax.plot(
        x,
        curve,
        color=color,
        linewidth=2,
        label="Fitted normal distribution",
    )
    ax.legend()

    return ax

