import base64
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding


def task_func(num, from_base, to_base, private_key, alphabet):
    if isinstance(from_base, bool) or not isinstance(from_base, int) or not 2 <= from_base <= 36:
        raise ValueError("from_base must be between 2 and 36")

    if isinstance(to_base, bool) or not isinstance(to_base, int) or not 2 <= to_base <= 36:
        raise ValueError("to_base must be between 2 and 36")

    if not isinstance(alphabet, str) or len(alphabet) != 64:
        raise ValueError("alphabet must contain exactly 64 characters")

    if len(set(alphabet)) != 64:
        raise ValueError("alphabet characters must be unique")

    number_text = str(num)
    if not number_text:
        raise ValueError("num must not be empty")

    value = int(number_text, from_base)
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

    if value == 0:
        converted = "0"
    else:
        sign = "-" if value < 0 else ""
        value = abs(value)
        result = []

        while value:
            value, remainder = divmod(value, to_base)
            result.append(digits[remainder])

        converted = sign + "".join(reversed(result))

    signature = private_key.sign(
        converted.encode("utf-8"),
        padding.PKCS1v15(),
        hashes.SHA256(),
    )

    encoded = base64.b64encode(signature).decode("ascii")
    standard_alphabet = (
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz"
        "0123456789+/"
    )

    return encoded.translate(str.maketrans(standard_alphabet, alphabet))

