import numpy as np
from sympy import symbols, solve


def task_func(precision=2, seed=0):
    if not isinstance(precision, (int, np.integer)) or precision < 0:
        raise ValueError("precision must be a non-negative integer")

    rng = np.random.default_rng(seed)

    a, b, c = rng.integers(-10, 11, size=3)
    while a == 0:
        a = rng.integers(-10, 11)

    discriminant = b * b - 4 * a * c
    sqrt_discriminant = np.sqrt(complex(discriminant))

    roots = (
        (-b + sqrt_discriminant) / (2 * a),
        (-b - sqrt_discriminant) / (2 * a),
    )

    return tuple(
        complex(
            round(root.real, precision),
            round(root.imag, precision),
        )
        for root in roots
    )

