def _validate_value(value, name):
    if isinstance(value, bool):
        raise ValueError(f'{name} must be a non-negative integer')

    if isinstance(value, int):
        result = value
    elif isinstance(value, str):
        try:
            result = int(value.strip())
        except ValueError as exc:
            raise ValueError(
                f'{name} must be a non-negative integer'
            ) from exc
    else:
        raise ValueError(f'{name} must be a non-negative integer')

    if result < 0:
        raise ValueError(f'{name} must be non-negative')

    return result


def task_func(goals, penalties, csv_file_path=CSV_FILE_PATH):
    goals = _validate_value(goals, 'goals')
    penalties = _validate_value(penalties, 'penalties')

    if not os.path.exists(csv_file_path):
        raise FileNotFoundError(csv_file_path)

    existing_goals = 0
    existing_penalties = 0

    with open(csv_file_path, 'r', newline='', encoding='utf-8') as file:
        rows = list(csv.reader(file))

    if rows:
        header = rows[0]
        normalized_header = [column.strip().lower() for column in header]

        if 'goals' not in normalized_header or 'penalties' not in normalized_header:
            raise ValueError("CSV must contain 'goals' and 'penalties' columns")

        goals_index = normalized_header.index('goals')
        penalties_index = normalized_header.index('penalties')
        data_rows = []

        for row_number, row in enumerate(rows[1:], start=2):
            if not row or not any(cell.strip() for cell in row):
                continue

            if row[0].strip().lower() == 'total':
                continue

            if len(row) <= max(goals_index, penalties_index):
                raise ValueError(f'Malformed row {row_number}')

            try:
                row_goals = int(row[goals_index].strip())
                row_penalties = int(row[penalties_index].strip())
            except ValueError as exc:
                raise ValueError(
                    f'Malformed numeric value in row {row_number}'
                ) from exc

            if row_goals < 0 or row_penalties < 0:
                raise ValueError(f'Negative value in row {row_number}')

            existing_goals += row_goals
            existing_penalties += row_penalties
            data_rows.append(row)
    else:
        header = ['team', 'goals', 'penalties']
        data_rows = []

    total_goals = existing_goals + goals
    total_penalties = existing_penalties + penalties

    output_rows = [
        header,
        *data_rows,
        ['Total', str(total_goals), str(total_penalties)]
    ]

    directory = os.path.dirname(os.path.abspath(csv_file_path))
    file_descriptor, temporary_path = tempfile.mkstemp(
        dir=directory,
        prefix='.match_data_',
        suffix='.tmp'
    )
    os.close(file_descriptor)

    try:
        with open(temporary_path, 'w', newline='', encoding='utf-8') as file:
            csv.writer(file).writerows(output_rows)

        os.replace(temporary_path, csv_file_path)
    finally:
        if os.path.exists(temporary_path):
            os.remove(temporary_path)

    return Counter({
        'goals': total_goals,
        'penalties': total_penalties
    })

