import re
import glob
import os
from docx import Document


def task_func(directory_path: str) -> int:
    def protect_paragraph(paragraph) -> None:
        for run in paragraph.runs:
            run.text = re.sub(r'"', r'\\"', run.text)

    def protect_table(table) -> None:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    protect_paragraph(paragraph)
                for nested_table in cell.tables:
                    protect_table(nested_table)

    processed = 0

    for file_path in glob.glob(os.path.join(directory_path, "*.docx")):
        if not os.path.isfile(file_path):
            continue

        try:
            document = Document(file_path)

            for paragraph in document.paragraphs:
                protect_paragraph(paragraph)

            for table in document.tables:
                protect_table(table)

            processed_parts = set()

            for section in document.sections:
                for container in (section.header, section.footer):
                    part_id = id(container.part)
                    if part_id in processed_parts:
                        continue

                    processed_parts.add(part_id)

                    for paragraph in container.paragraphs:
                        protect_paragraph(paragraph)

                    for table in container.tables:
                        protect_table(table)

            document.save(file_path)
            processed += 1
        except Exception:
            continue

    return processed

