import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        data = response.text

        bracket_depth = 0
        in_string = False
        escaped = False
        depths = [0] * (len(data) + 1)

        for index, char in enumerate(data):
