import numpy as np
from sklearn.cluster import KMeans
import matplotlib.pyplot as plt


def task_func(
    P: np.ndarray,
    T: np.ndarray,
    n_clusters: int = 3,
    random_state: int = 0,
    n_init: int = 10,
) -> (np.ndarray, plt.Axes):
    if not isinstance(P, np.ndarray) or P.ndim != 2:
        raise ValueError("P must be a 2D NumPy array.")

    if not isinstance(T, np.ndarray) or T.ndim != 3:
        raise ValueError("T must be a 3D NumPy array.")

    if P.shape[1] != T.shape[0]:
        raise ValueError(
            "The number of columns in P must match the first dimension of T."
        )

    for name, array in (("P", P), ("T", T)):
        if not np.issubdtype(array.dtype, np.number) or np.iscomplexobj(array):
            raise ValueError(f"{name} must contain real numeric values.")
        if not np.all(np.isfinite(array)):
            raise ValueError(f"{name} must contain only finite values.")

    if P.size == 0 or T.size == 0:
        raise ValueError("P and T must not be empty.")

    if not isinstance(n_clusters, (int, np.integer)) or isinstance(n_clusters, bool):
        raise ValueError("n_clusters must be an integer.")
    if n_clusters < 1:
        raise ValueError("n_clusters must be at least 1.")

    if not isinstance(n_init, (int, np.integer)) or isinstance(n_init, bool):
        raise ValueError("n_init must be an integer.")
    if n_init < 1:
        raise ValueError("n_init must be at least 1.")

    product = np.tensordot(P, T, axes=([1], [0]))
    flattened = product.ravel()

    if flattened.size == 0:
        raise ValueError("The matrix-tensor product must not be empty.")

    if n_clusters > flattened.size:
        raise ValueError(
            "n_clusters cannot exceed the number of flattened values."
        )

    data = flattened.reshape(-1, 1)

    model = KMeans(
        n_clusters=int(n_clusters),
        random_state=random_state,
        n_init=int(n_init),
    )
    cluster_result = model.fit_predict(data)

    _, ax = plt.subplots()
    ax.scatter(
        np.arange(flattened.size),
        flattened,
        c=cluster_result,
        cmap="viridis",
    )
    ax.set_title("KMeans Clustering Visualization")
    ax.set_xlabel("Index")
    ax.set_ylabel("Value")

    return cluster_result, ax

