        backup_path = os.path.join(BACKUP_DIR, directory_name)

        if not os.path.isdir(backup_path):
            return (
                f"Backup for directory {directory} does not exist. "
                "Cannot rollback update."
            )

        temporary_path = f"{normalized_directory}.rollback_tmp"
        if os.path.lexists(temporary_path):
            if os.path.isdir(temporary_path) and not os.path.islink(temporary_path):
                shutil.rmtree(temporary_path)
            else:
                os.remove(temporary_path)

        shutil.copytree(backup_path, temporary_path)

        if os.path.lexists(normalized_directory):
            if os.path.isdir(normalized_directory) and not os.path.islink(normalized_directory):
                shutil.rmtree(normalized_directory)
            else:
                os.remove(normalized_directory)

        os.replace(temporary_path, normalized_directory)
        return directory

    except Exception as error:
        return f"Cannot rollback update: {error}"

