import bs4
import requests
import re
import json
from urllib.parse import unquote, urlparse


def task_func(url: str, output_path: str) -> list:
    phone_pattern = re.compile(
        r"(?<![\d\w])(?:"
        r"\+\s*\d{1,3}(?:[\s().-]*\d){7,14}"
        r"|(?:\(\s*)?\d(?:[\s().-]*\d){9,14}"
        r")(?![\d\w])"
    )

    if url.lower().startswith(("http://", "https://")):
        try:
            response = requests.get(url, timeout=15)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as exc:
            raise RuntimeError(f"Failed to fetch URL: {url}") from exc
    else:
        if url.lower().startswith("file://"):
            parsed = urlparse(url)
            file_path = unquote(parsed.path)
            if parsed.netloc and parsed.netloc.lower() != "localhost":
                file_path = f"//{parsed.netloc}{file_path}"
            elif re.match(r"^/[A-Za-z]:", file_path):
                file_path = file_path[1:]
        else:
            file_path = url

        try:
            with open(file_path, "r", encoding="utf-8") as file:
                content = file.read()
        except (OSError, UnicodeError, TypeError) as exc:
            raise RuntimeError(f"Failed to read local file: {url}") from exc

    soup = bs4.BeautifulSoup(content, "html.parser")

    for element in soup(["script", "style", "noscript", "template"]):
        element.decompose()

    text_parts = [soup.get_text(" ")]

    for link in soup.find_all("a", href=True):
        href = unquote(str(link["href"]))
        if href.lower().startswith("tel:"):
            text_parts.append(href[4:])

    numbers = []
    seen = set()

    for part in text_parts:
        for match in phone_pattern.finditer(part):
            number = match.group(0).strip()
            key = re.sub(r"\D", "", number)

            if key and key not in seen:
                seen.add(key)
                numbers.append(number)

    try:
        with open(output_path, "w", encoding="utf-8") as file:
            json.dump(numbers, file, ensure_ascii=False, indent=2)
    except (OSError, TypeError) as exc:
        raise RuntimeError(f"Failed to write output file: {output_path}") from exc

    return numbers

