import numpy as np
from scipy.optimize import curve_fit


def task_func(x, y, labels):
    import matplotlib.pyplot as plt

    def exponential_model(x_value, a, b, c):
        return a * np.exp(-b * x_value) + c

    try:
        x_sets = list(x)
        y_sets = list(y)
        label_sets = list(labels)
    except TypeError as exc:
        raise ValueError("x, y, and labels must be iterable.") from exc

    if not x_sets:
        raise ValueError("At least one dataset is required.")

    if len(x_sets) != len(y_sets) or len(x_sets) != len(label_sets):
        raise ValueError("x, y, and labels must have matching lengths.")

    fig, ax = plt.subplots()

    for x_data, y_data, label in zip(x_sets, y_sets, label_sets):
        try:
            x_array = np.asarray(x_data, dtype=float)
            y_array = np.asarray(y_data, dtype=float)
        except (TypeError, ValueError) as exc:
            raise ValueError("Dataset values must be numeric.") from exc

        if x_array.ndim != 1 or y_array.ndim != 1:
            raise ValueError("Each dataset must be one-dimensional.")

        if x_array.size < 3:
            raise ValueError("Each dataset must contain at least three points.")

        if x_array.size != y_array.size:
            raise ValueError("Each x and y dataset must have equal lengths.")

        if not np.all(np.isfinite(x_array)) or not np.all(np.isfinite(y_array)):
            raise ValueError("Dataset values must be finite.")

        x_range = float(np.ptp(x_array))
        if x_range == 0:
            raise ValueError("Each x dataset must contain distinct values.")

        c_initial = float(np.min(y_array))
        a_initial = float(np.max(y_array) - c_initial)
        if a_initial == 0:
            a_initial = 1.0

        try:
            parameters, _ = curve_fit(
                exponential_model,
                x_array,
                y_array,
                p0=(a_initial, 1.0 / x_range, c_initial),
                maxfev=100000,
            )
        except (RuntimeError, ValueError, OverflowError) as exc:
            raise ValueError(
                "Unable to fit an exponential curve to a dataset."
            ) from exc

        x_curve = np.linspace(np.min(x_array), np.max(x_array), 200)
        y_curve = exponential_model(x_curve, *parameters)
        ax.plot(x_curve, y_curve, label=label)

    ax.set_xlabel("x")
    ax.set_ylabel("f(x)")
    ax.legend()
    ax.grid(True)

    return fig

