import heapq
from scipy import stats


def task_func(df, col1, col2, N=10):
    if col1 not in df.columns or col2 not in df.columns:
        raise ValueError("Specified columns must be present in the DataFrame.")

    if N <= 1:
        raise ValueError("N must be greater than 1.")

    differences = (df[col1] - df[col2]).abs()
    indices = heapq.nlargest(
        min(N, len(df)),
        range(len(df)),
        key=lambda index: differences.iloc[index],
    )

    result = stats.ttest_ind(
        df[col1].iloc[indices],
        df[col2].iloc[indices],
    )

    return float(result.pvalue)

