import pandas as pd
from sklearn.feature_extraction.text import CountVectorizer
import matplotlib.pyplot as plt

# Constants
STOP_WORDS = ["a", "an", "the", "in", "on", "at", "and", "or"]


def task_func(file_path, save_path=None):
    try:
        try:
            data = pd.read_csv(file_path, header=None)
        except FileNotFoundError as exc:
            raise FileNotFoundError(f"File not found: {file_path}") from exc

        if data.empty:
            texts = []
        else:
            first_value = data.iloc[0, 0]
            if isinstance(first_value, str) and first_value.strip() == "Text":
                data = data.iloc[1:]

            texts = data.iloc[:, 0].fillna("").astype(str).tolist()

        top_words = []
        top_counts = []

        if texts:
            vectorizer = CountVectorizer(stop_words=STOP_WORDS)
            try:
                matrix = vectorizer.fit_transform(texts)
            except ValueError as exc:
                if "empty vocabulary" not in str(exc).lower():
                    raise
            else:
                frequencies = matrix.sum(axis=0).A1
                words = vectorizer.get_feature_names_out()
                ranked_indices = sorted(
                    range(len(words)),
                    key=lambda index: (-frequencies[index], index),
                )[:10]
                top_words = [words[index] for index in ranked_indices]
                top_counts = [frequencies[index] for index in ranked_indices]

        fig, ax = plt.subplots()
        ax.bar(top_words, top_counts)
        ax.set_xlabel("Words")
        ax.set_ylabel("Frequency")
        ax.set_title("Top 10 Most Common Words")
        ax.tick_params(axis="x", rotation=45)
        fig.tight_layout()

        if save_path is not None:
            fig.savefig(save_path)
            plt.close(fig)
            return None

        return ax

    except FileNotFoundError:
        raise
    except Exception as error:
        print(error)
        return None

