import re
import pandas as pd
from datetime import datetime
import os


def task_func(log_file):
    pattern = re.compile(
        r"^(?P<type>[^:\r\n]+?)\s*:\s*\[(?P<timestamp>[^\]\r\n]*)\]\s*-\s*(?P<message>.*)$"
    )

    records = []

    with open(log_file, "r", encoding="utf-8") as file:
        for line in file:
            match = pattern.fullmatch(line.rstrip("\r\n"))
            if not match:
                continue

            log_type = match.group("type").strip()
            timestamp = match.group("timestamp").strip()
            message = match.group("message")

            try:
                datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
            except ValueError as exc:
                raise ValueError(f"Invalid timestamp: {timestamp}") from exc

            if not log_type:
                continue

            records.append(
                {
                    "type": log_type,
                    "timestamp": timestamp,
                    "message": message,
                }
            )

    if not records:
        raise ValueError("No valid log entries found")

    input_path = os.fsdecode(os.fspath(log_file))
    output_path = os.path.splitext(input_path)[0] + "_structured.csv"

    pd.DataFrame(records, columns=["type", "timestamp", "message"]).to_csv(
        output_path, index=False
    )

    return output_path

