import os
import glob
from collections import Counter


def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.isdir(directory):
        raise OSError(f"Directory does not exist: {directory}")

    requested = set(extensions)
    counts = Counter({extension: 0 for extension in requested}) if keep_zero else Counter()

    pattern = os.path.join(directory, "**", "*")
    for path in glob.iglob(pattern, recursive=True):
        if os.path.isfile(path):
            extension = os.path.splitext(path)[1]
            if extension in requested:
                counts[extension] += 1

    return counts

