import re
import os
import zipfile


def task_func(directory, pattern=r'^(.*?)-\d+\.zip$'):
    if not os.path.isdir(directory):
        raise NotADirectoryError(directory)

    extracted_dirs = []
    seen_dirs = set()

    for filename in os.listdir(directory):
        archive_path = os.path.join(directory, filename)

        if not os.path.isfile(archive_path):
            continue

        if re.match(pattern, filename) is None:
            continue

        prefix = filename.rsplit("-", 1)[0]
        if not prefix or prefix in {".", ".."}:
            raise ValueError(f"Invalid extraction directory name: {prefix!r}")

        if os.path.isabs(prefix) or os.path.basename(prefix) != prefix:
            raise ValueError(f"Unsafe extraction directory name: {prefix!r}")

        extraction_dir = os.path.join(directory, prefix)
        os.makedirs(extraction_dir, exist_ok=True)

        root = os.path.realpath(extraction_dir)

        with zipfile.ZipFile(archive_path, "r") as archive:
            for info in archive.infolist():
                member_name = info.filename.replace("\\", "/")
                normalized_name = os.path.normpath(member_name)

                if (
                    normalized_name in {".", ".."}
                    or normalized_name.startswith(".." + os.sep)
                    or os.path.isabs(normalized_name)
                ):
                    raise ValueError(f"Unsafe ZIP entry: {info.filename!r}")

                target = os.path.realpath(
                    os.path.join(extraction_dir, normalized_name)
                )

                if os.path.commonpath((root, target)) != root:
                    raise ValueError(f"Unsafe ZIP entry: {info.filename!r}")

                if info.is_dir():
                    os.makedirs(target, exist_ok=True)
                    continue

                if ((info.external_attr >> 16) & 0o170000) == 0o120000:
                    raise ValueError(
                        f"Symbolic links are not allowed: {info.filename!r}"
                    )

                os.makedirs(os.path.dirname(target), exist_ok=True)

                if os.path.islink(target):
                    raise ValueError(
                        f"Symbolic link target is not allowed: {info.filename!r}"
                    )

                with archive.open(info) as source, open(target, "wb") as dest:
                    while chunk := source.read(1024 * 1024):
                        dest.write(chunk)

        key = os.path.abspath(extraction_dir)
        if key not in seen_dirs:
            seen_dirs.add(key)
            extracted_dirs.append(extraction_dir)

    return extracted_dirs

