import numpy as np
from itertools import zip_longest

def task_func(l1, l2,THRESHOLD = 0.5):
    closest_element = None
    smallest_difference = np.inf

    for first, second in zip_longest(l1, l2, fillvalue=None):
        for element in (first, second):
            if element is None or isinstance(element, (bool, np.bool_)):
                continue

            try:
                value = float(element)
                difference = float(np.abs(value - THRESHOLD))
            except (TypeError, ValueError, OverflowError):
                continue

            if not np.isfinite(difference):
                continue

            if difference < smallest_difference:
                smallest_difference = difference
                closest_element = value

    if closest_element is None:
        raise ValueError("No numeric elements were provided.")

    return closest_element

