import matplotlib.pyplot as plt
from scipy import stats
from sklearn.preprocessing import StandardScaler


def task_func(data, column, outlier_z_score):
    """Identify and remove outliers from a dataset column using Z-scores."""

    if isinstance(outlier_z_score, (bool, np.bool_)):
        raise ValueError("outlier_z_score must be a non-negative number.")

    try:
        threshold = float(outlier_z_score)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "outlier_z_score must be a non-negative number."
        ) from exc

    if not np.isfinite(threshold) or threshold < 0:
        raise ValueError(
            "outlier_z_score must be a non-negative finite number."
        )

    try:
        data_array = np.asarray(data)
    except Exception as exc:
        raise ValueError("data must be convertible to a NumPy array.") from exc

    if data_array.ndim != 2:
        raise ValueError("data must be a two-dimensional array.")

    try:
        column_value = np.asarray(column).item()
    except (ValueError, TypeError):
        raise ValueError("column must be a valid integer index.")

    if isinstance(column_value, (bool, np.bool_)):
        raise ValueError("column must be a valid integer index.")

    try:
        column_index = int(column_value)
    except (TypeError, ValueError) as exc:
        raise ValueError("column must be a valid integer index.") from exc

    if column_index != column_value:
        raise ValueError("column must be a valid integer index.")

    if not 0 <= column_index < data_array.shape[1]:
        raise IndexError("column index is out of range.")

    original_data = data_array.copy()

    try:
        selected_values = np.asarray(
            data_array[:, column_index], dtype=float
        )
    except (TypeError, ValueError) as exc:
        raise ValueError("The selected column must contain numeric values.") from exc

    if not np.all(np.isfinite(selected_values)):
        raise ValueError(
            "The selected column must not contain NaN or infinite values."
        )

    if selected_values.size == 0:
        z_scores = np.array([], dtype=float)
    elif selected_values.size == 1 or np.all(
        selected_values == selected_values[0]
    ):
        z_scores = np.zeros(selected_values.shape, dtype=float)
    else:
        scaler = StandardScaler()
        z_scores = scaler.fit_transform(
            selected_values.reshape(-1, 1)
        ).ravel()

    outlier_mask = np.abs(z_scores) > threshold
    outlier_indices = np.flatnonzero(outlier_mask)
    data_without_outliers = original_data[~outlier_mask].copy()
    retained_indices = np.flatnonzero(~outlier_mask)

    fig, axes = plt.subplots(1, 2, figsize=(12, 5))

    axes[0].scatter(np.arange(selected_values.size), selected_values)
    axes[0].set_title("Data with Outliers")
    axes[0].set_xlabel("Row Index")
    axes[0].set_ylabel("Value")

    axes[1].scatter(
        retained_indices,
        selected_values[~outlier_mask],
    )
    axes[1].set_title("Data without Outliers")
    axes[1].set_xlabel("Row Index")
    axes[1].set_ylabel("Value")

    fig.tight_layout()
    plt.show()

    return original_data, data_without_outliers, outlier_indices

