        raise ValueError("rows and columns must be non-negative")

    def generate_value(data_type):
        if data_type is str:
            letters = np.random.choice(list("abcdefghijklmnopqrstuvwxyz"), size=5)
            return "".join(letters)

        if data_type is int:
            return int(np.random.randint(0, 10))

        if data_type is float:
            return float(np.random.randint(0, 10))

        if data_type is list:
            length = int(np.random.randint(1, 6))
            return [int(value) for value in np.random.randint(0, 10, size=length)]

        if data_type is tuple:
            length = int(np.random.randint(1, 6))
            return tuple(
                int(value) for value in np.random.randint(0, 10, size=length)
            )

        if data_type is dict:
            length = int(np.random.randint(1, 6))
            keys = np.random.choice(10, size=length, replace=False)
            return {
                int(key): int(np.random.randint(0, 10))
                for key in keys
            }

        if data_type is set:
            length = int(np.random.randint(1, 6))
            values = np.random.choice(10, size=length, replace=False)
            return {int(value) for value in values}

        raise ValueError("Unsupported data type")

    if columns == 0:
        return pd.DataFrame(index=range(rows))

    data = {
        f"col{column_index}": [
            generate_value(choice(DATA_TYPES)) for _ in range(rows)
        ]
        for column_index in range(columns)
    }

    return pd.DataFrame(data)

