import re
import os
import glob


def task_func(dir_path: str) -> list:
    if not os.path.isdir(dir_path):
        raise FileNotFoundError(f"Directory not found: {dir_path}")

    file_paths = [
        path
        for path in glob.glob(os.path.join(dir_path, "*"), include_hidden=True)
        if os.path.isfile(path)
    ]

    new_names = [
        re.sub(r"[^A-Za-z0-9]", "", os.path.basename(path))
        for path in file_paths
    ]

    if any(not name for name in new_names):
        raise ValueError("A filename cannot be empty after sanitization.")

    normalized_names = [os.path.normcase(name) for name in new_names]
    if len(normalized_names) != len(set(normalized_names)):
        raise FileExistsError("Multiple files would receive the same name.")

    source_paths = {os.path.normcase(path) for path in file_paths}

    for path, new_name in zip(file_paths, new_names):
        destination = os.path.join(dir_path, new_name)
        normalized_destination = os.path.normcase(destination)

        if (
            os.path.lexists(destination)
            and normalized_destination not in source_paths
        ):
            raise FileExistsError(f"Destination already exists: {destination}")

    for path, new_name in zip(file_paths, new_names):
        destination = os.path.join(dir_path, new_name)
        if os.path.normcase(path) != os.path.normcase(destination):
            os.rename(path, destination)

    return new_names

