from datetime import datetime
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import numbers


def task_func(start_time, end_time, step, amplitude, period, seed=0):
    def to_utc_timestamp(value):
        try:
            timestamp = pd.Timestamp(value)
        except Exception as exc:
            raise ValueError("Invalid datetime value") from exc

        if pd.isna(timestamp):
            raise ValueError("Datetime cannot be NaT")

        if timestamp.tzinfo is None:
            return timestamp.tz_localize("UTC")
        return timestamp.tz_convert("UTC")

    def to_timedelta(value):
        try:
            if isinstance(value, numbers.Real):
                duration = pd.to_timedelta(value, unit="s")
            else:
                duration = pd.to_timedelta(value)
        except Exception as exc:
            raise ValueError("Invalid time duration") from exc

        if pd.isna(duration):
            raise ValueError("Time duration cannot be missing")

        return duration

    start = to_utc_timestamp(start_time)
    end = to_utc_timestamp(end_time)
    step_delta = to_timedelta(step)
    period_delta = to_timedelta(period)

    if end < start:
        raise ValueError("end_time must not be earlier than start_time")
    if step_delta <= pd.Timedelta(0):
        raise ValueError("step must be positive")
    if period_delta <= pd.Timedelta(0):
        raise ValueError("period must be positive")

    try:
        amplitude = float(amplitude)
    except (TypeError, ValueError) as exc:
        raise ValueError("amplitude must be numeric") from exc

    if not np.isfinite(amplitude):
        raise ValueError("amplitude must be finite")

    timestamps = pd.date_range(
        start=start,
        end=end,
        freq=step_delta,
    )

    elapsed_seconds = (timestamps - start).total_seconds()
    period_seconds = period_delta.total_seconds()

    if period_seconds <= 0 or not np.isfinite(period_seconds):
        raise ValueError("period must be a finite positive duration")

    values = amplitude * np.sin(
        2 * np.pi * elapsed_seconds / period_seconds
    )

    _, ax = plt.subplots()
    ax.plot(timestamps, values)
    ax.set_xlabel("Timestamp")
    ax.set_ylabel("Value")
    ax.set_title("Time Series with Seasonality")

    return ax

