import subprocess
import psutil
import time
import os


def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")

    if not os.path.isfile(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    try:
        timeout = float(timeout)
    except (TypeError, ValueError) as exc:
        raise ValueError("timeout must be a non-negative number") from exc

    if timeout < 0 or timeout != timeout:
        raise ValueError("timeout must be a non-negative number")

    process = subprocess.Popen(["bash", script_path])
    monitored_process = psutil.Process(process.pid)

    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.monotonic()
    sample_interval = 0.05

    try:
        while process.poll() is None:
            elapsed = time.monotonic() - start_time
            if elapsed >= timeout:
                break

            try:
                if monitored_process.status() == psutil.STATUS_ZOMBIE:
                    break

                memory_usage += monitored_process.memory_info().rss

                remaining = timeout - elapsed
                interval = min(sample_interval, remaining)
                cpu_usage += monitored_process.cpu_percent(interval=interval)

            except (
                psutil.NoSuchProcess,
                psutil.AccessDenied,
                psutil.ZombieProcess,
            ):
                break

        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=0.2)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()
        else:
            process.wait()

    finally:
        if process.poll() is None:
            try:
                process.kill()
            except ProcessLookupError:
                pass
            process.wait()

    return {
        "CPU Usage": cpu_usage,
        "Memory Usage": memory_usage,
    }

