import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    if not isinstance(data, pd.DataFrame):
        raise TypeError("data must be a pandas DataFrame")

    if not isinstance(mapping, dict):
        raise TypeError("mapping must be a dictionary")

    if any(not isinstance(key, str) or not key for key in mapping):
        raise ValueError("Mapping keys must be non-empty strings")

    if any(not isinstance(value, str) for value in mapping.values()):
        raise TypeError("Mapping values must be strings")

    result = data.copy()

    if not mapping:
        return result

    keys = sorted(mapping, key=len, reverse=True)
    pattern = re.compile(
        r"(?<!\w)(?:"
        + "|".join(re.escape(key) for key in keys)
        + r")(?!\w)"
    )

    def replace_cell(value):
        if isinstance(value, str):
            return pattern.sub(lambda match: mapping[match.group(0)], value)
        return value

    for row_index in range(result.shape[0]):
        for column_index in range(result.shape[1]):
            value = result.iat[row_index, column_index]
            if isinstance(value, str):
                result.iat[row_index, column_index] = replace_cell(value)

    return result

