import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    if "value" not in df.columns or df.empty:
        raise ValueError("df must contain a non-empty 'value' column")

    if not isinstance(freq, str) or not freq.strip():
        raise ValueError("freq must be a valid frequency string")

    try:
        offset = pd.tseries.frequencies.to_offset(freq.strip())
    except (TypeError, ValueError):
        raise ValueError("freq must be a valid frequency string")

    if getattr(offset, "n", 1) <= 0:
        raise ValueError("freq must be a valid positive frequency string")

    if not isinstance(decomposition_model, str) or decomposition_model not in {
        "additive",
        "multiplicative",
    }:
        raise ValueError(
            "decomposition_model must be 'additive' or 'multiplicative'"
        )

    values = df["value"]

    if (
        not pd.api.types.is_numeric_dtype(values)
        or pd.api.types.is_bool_dtype(values)
        or values.isna().any()
    ):
        raise ValueError("'value' must contain valid numeric data")

    try:
        values = values.astype(float)
    except (TypeError, ValueError):
        raise ValueError("'value' must contain valid numeric data")

    if values.isin([float("inf"), float("-inf")]).any():
        raise ValueError("'value' must contain finite numeric data")

    if decomposition_model == "multiplicative" and (values <= 0).any():
        raise ValueError(
            "multiplicative decomposition requires strictly positive values"
        )

    rule_code = str(getattr(offset, "rule_code", "")).upper()
    multiplier = abs(int(getattr(offset, "n", 1)))

    if rule_code.startswith("W"):
        period = max(2, round(52 / multiplier))
    elif rule_code.startswith(("M", "ME", "MS")):
        period = max(2, round(12 / multiplier))
    elif rule_code.startswith(("Q", "QE", "QS")):
        period = max(2, round(4 / multiplier))
    elif rule_code.startswith(("A", "Y", "YE", "YS")):
        period = 2
    else:
        try:
            period = round(
                pd.Timedelta(days=7).value / offset.nanos
            )
        except (AttributeError, TypeError, ValueError, OverflowError):
            raise ValueError("freq is not suitable for decomposition")
        period = max(2, period)

    if len(values) < 2 * period:
        raise ValueError(
            "df must contain at least two complete seasonal cycles"
        )

    series = values.copy()

    if isinstance(series.index, pd.DatetimeIndex):
        if series.index.has_duplicates or series.index.hasnans:
            raise ValueError("df contains an invalid datetime index")
        series = series.sort_index()

    result = seasonal_decompose(
        series,
        model=decomposition_model,
        period=period,
    )

    figure = result.plot()
    axes = figure.axes[0]

    return result, axes

