import re
from datetime import time


def task_func(logs: list):
    error_times = []
    timestamp_pattern = re.compile(
        r"(?<!\d)(\d{2}):(\d{2}):(\d{2})(?:\.\d+)?"
    )
    error_pattern = re.compile(r"\berror\b", re.IGNORECASE)

    for log in logs:
        if not isinstance(log, str) or not error_pattern.search(log):
            continue

        for match in timestamp_pattern.finditer(log):
            hours, minutes, seconds = map(int, match.groups())

            try:
                error_times.append(time(hours, minutes, seconds))
            except ValueError:
                continue

    if not error_times:
        return {"list": [], "time": None}

    total_seconds = sum(
        current_time.hour * 3600
        + current_time.minute * 60
        + current_time.second
        for current_time in error_times
    )
    average_seconds = total_seconds // len(error_times)

    average_time = time(
        average_seconds // 3600,
        (average_seconds % 3600) // 60,
        average_seconds % 60,
    )

    return {"list": error_times, "time": average_time}

