COLUMNS = ['A', 'B', 'C', 'D', 'E']
def task_func(df, tuples, n_plots):
    import pandas as pd

    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if isinstance(n_plots, bool) or not isinstance(n_plots, int):
        raise TypeError("n_plots must be a non-negative integer")
    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    def is_pair(value):
        return (
            isinstance(value, (tuple, list))
            and len(value) == 2
            and isinstance(value[0], str)
        )

    if tuples is None:
        groups = []
    elif is_pair(tuples):
        groups = [[tuples]]
    else:
        try:
            items = list(tuples)
        except TypeError as exc:
            raise TypeError(
                "tuples must contain (column, value) pairs"
            ) from exc

        if all(is_pair(item) for item in items):
            groups = [items]
        else:
            groups = []
            for group in items:
                try:
                    group = list(group)
                except TypeError as exc:
                    raise TypeError(
                        "tuples must contain (column, value) pairs"
                    ) from exc
                if not all(is_pair(item) for item in group):
                    raise TypeError(
                        "tuples must contain (column, value) pairs"
                    )
                groups.append(group)

    for group in groups:
        for column, _ in group:
            if column not in COLUMNS:
                raise ValueError(f"Invalid column: {column}")
            if column not in df.columns:
                raise ValueError(f"Column not found in DataFrame: {column}")

    result = df.copy()

    for group in groups:
        if not group:
            continue

        matches = pd.Series(True, index=range(len(result)))
        for column, value in group:
            condition = result[column].eq(value).fillna(False)
            matches &= pd.Series(condition.to_numpy(), index=matches.index)

        result = result.loc[~matches.to_numpy()]

    if n_plots:
        missing = [column for column in COLUMNS if column not in df.columns]
        if missing:
            raise ValueError(f"Missing plotting columns: {missing}")

    plot_details = []

    for _ in range(n_plots):
        col_x, col_y = sample(COLUMNS, 2)
        plt.figure()
        plt.plot(result[col_x], result[col_y])
        plt.xlabel(col_x)
        plt.ylabel(col_y)
        plot_details.append((col_x, col_y))

    return result, plot_details

