import ast
import re


def task_func(text_file: str) -> list:
    with open(text_file, "r", encoding="utf-8") as file:
        text = file.read()

    token_pattern = re.compile(
        r"""(?<!\w)'(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*"|[{}]"""
    )
    tokens = list(token_pattern.finditer(text))
    dictionaries = []
    skip_until = -1

    for index, token_match in enumerate(tokens):
        if token_match.group() != "{" or token_match.start() < skip_until:
            continue

        depth = 0
        end = None

        for closing_match in tokens[index:]:
            token = closing_match.group()

            if token == "{":
                depth += 1
            elif token == "}":
                depth -= 1
                if depth == 0:
                    end = closing_match.end()
                    break

        if end is None:
            continue

        candidate = text[token_match.start():end]

        try:
            value = ast.literal_eval(candidate)
        except (SyntaxError, ValueError):
            continue

        if isinstance(value, dict):
            dictionaries.append(value)
            skip_until = end

    return dictionaries

