from scipy import stats
import math
import numbers
from decimal import Decimal, ROUND_DOWN


def task_func(n_data_points=5000, min_value=0.0, max_value=10.0):
    if isinstance(n_data_points, bool) or not isinstance(
        n_data_points, numbers.Integral
    ):
        raise TypeError("n_data_points must be an integer")
    if n_data_points <= 0:
        raise ValueError("n_data_points must be greater than zero")

    if (
        isinstance(min_value, bool)
        or isinstance(max_value, bool)
        or not isinstance(min_value, numbers.Real)
        or not isinstance(max_value, numbers.Real)
    ):
        raise TypeError("min_value and max_value must be numeric")

    if not math.isfinite(min_value) or not math.isfinite(max_value):
        raise ValueError("range values must be finite")
    if min_value > max_value:
        raise ValueError("min_value must not exceed max_value")

    data = []
    for _ in range(n_data_points):
