import pandas as pd
from datetime import datetime, timedelta
import random
import math
from numbers import Real


def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if isinstance(epoch_milliseconds, bool) or not isinstance(
        epoch_milliseconds, Real
    ):
        raise ValueError("epoch_milliseconds must be numeric")

    if not math.isfinite(float(epoch_milliseconds)):
        raise ValueError("epoch_milliseconds must be finite")

    try:
        start_datetime = datetime.fromtimestamp(float(epoch_milliseconds) / 1000)
    except (OverflowError, OSError, ValueError) as exc:
        raise ValueError("Invalid epoch timestamp") from exc

    current_datetime = datetime.now()

    if start_datetime > current_datetime:
        raise ValueError("epoch_milliseconds cannot be in the future")

    if isinstance(products, (str, bytes)):
        raise ValueError("products must contain exactly five unique strings")

    try:
        product_list = list(products)
    except TypeError as exc:
        raise ValueError("products must contain exactly five unique strings") from exc

    if (
        len(product_list) != 5
        or any(not isinstance(product, str) for product in product_list)
        or len(set(product_list)) != 5
    ):
        raise ValueError("products must contain exactly five unique strings")

    random.seed(random_seed)

    records = []
    current_date = start_datetime.date()
    end_date = current_datetime.date()

    while current_date <= end_date:
        date_value = datetime.combine(current_date, datetime.min.time())

        for product in product_list:
            records.append(
                {
                    "Product": product,
                    "Date": date_value,
                    "Sales": random.randint(10, 50),
                }
            )

        current_date += timedelta(days=1)

    return pd.DataFrame(records, columns=["Product", "Date", "Sales"])

