import re
import nltk
from gensim.models import Word2Vec

# Constants
ALPHANUMERIC = re.compile('[\W_]+')


def task_func(texts, stopwords=None):
    if isinstance(texts, str):
        raise TypeError("texts must be an iterable of strings")

    texts = list(texts)

    if any(not isinstance(text, str) for text in texts):
        raise TypeError("each item in texts must be a string")

    if stopwords is None:
        stopwords = nltk.corpus.stopwords.words("english")

    normalized_stopwords = set()
    for word in stopwords:
        cleaned_word = ALPHANUMERIC.sub(" ", str(word).lower())
        normalized_stopwords.update(cleaned_word.split())

    tokenized_texts = []
    for text in texts:
        cleaned_text = ALPHANUMERIC.sub(" ", text.lower())
        tokens = [
            token
            for token in cleaned_text.split()
            if token not in normalized_stopwords
        ]
        tokenized_texts.append(tokens)

    if not any(tokenized_texts):
        raise ValueError("texts must contain at least one usable word")

    return Word2Vec(
        sentences=tokenized_texts,
        min_count=1,
    )

