import pandas as pd
from itertools import combinations


def task_func(df, tuples, n_plots):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    missing_columns = [column for column in COLUMNS if column not in df.columns]
    if missing_columns:
        raise ValueError(f"Missing required columns: {missing_columns}")

    if not isinstance(n_plots, int) or isinstance(n_plots, bool) or n_plots < 0:
        raise ValueError("n_plots must be a non-negative integer")

    removal_mask = pd.Series(False, index=df.index)

    try:
        removal_values = list(tuples)
    except TypeError as exc:
        raise ValueError("tuples must be an iterable of five-value tuples") from exc

    for values in removal_values:
        try:
            values = tuple(values)
        except TypeError as exc:
            raise ValueError(
                "Each removal item must contain exactly five values"
            ) from exc

        if len(values) != len(COLUMNS):
            raise ValueError("Each removal item must contain exactly five values")

        row_mask = pd.Series(True, index=df.index)

        for column, value in zip(COLUMNS, values):
            try:
                is_missing = bool(pd.isna(value))
            except (TypeError, ValueError) as exc:
                raise ValueError("Removal values must be scalar values") from exc

            if is_missing:
                row_mask &= df[column].isna()
            else:
                row_mask &= df[column].eq(value).fillna(False)

        removal_mask |= row_mask

    filtered_df = df.loc[~removal_mask].copy()

    column_pairs = list(combinations(COLUMNS, 2))
    selected_pairs = sample(column_pairs, min(n_plots, len(column_pairs)))

    axes = [
        sns.scatterplot(data=filtered_df, x=x_column, y=y_column)
        for x_column, y_column in selected_pairs
    ]

    return filtered_df, axes

