    def close_client(client):
        clients.discard(client)
        output_queues.pop(client, None)
        pending.pop(client, None)
        try:
            client.close()
        except OSError:
            pass

    try:
        server_port = int(server_port)
        buffer_size = int(buffer_size)
        duration = float(run_duration)

        if not 0 <= server_port <= 65535:
            return "Server failed: server_port must be between 0 and 65535"
        if buffer_size <= 0:
            return "Server failed: buffer_size must be positive"
        if duration < 0 or duration != duration:
            return "Server failed: run_duration must be non-negative and finite"
        if duration == float("inf"):
            return "Server failed: run_duration must be finite"

        if duration == 0:
            return "Server operated for 0.00 seconds"

        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((server_address, server_port))
        server_socket.listen()
        server_socket.setblocking(False)

        deadline = start_time + timedelta(seconds=duration)

        while datetime.now() < deadline:
            readable = [server_socket, *clients]
            writable = [
                client
                for client in clients
                if client in pending or not output_queues[client].empty()
            ]
            exceptional = [server_socket, *clients]
            timeout = max(0.0, (deadline - datetime.now()).total_seconds())

            try:
                ready_read, ready_write, ready_exceptional = select.select(
                    readable, writable, exceptional, timeout
                )
            except InterruptedError:
                continue
            except OSError:
                break

            if server_socket in ready_exceptional:
                break

            for client in ready_exceptional:
                if client in clients:
                    close_client(client)

            if server_socket in ready_read:
                while True:
                    try:
                        client, _ = server_socket.accept()
                        client.setblocking(False)
                        clients.add(client)
                        output_queues[client] = queue.Queue()
                    except BlockingIOError:
                        break
                    except OSError:
                        break

            for client in ready_read:
                if client is server_socket or client not in clients:
                    continue

                try:
                    data = client.recv(buffer_size)
                    if not data:
                        close_client(client)
                        continue

                    timestamp = datetime.now().isoformat().encode()
                    output_queues[client].put(data + timestamp)
                except (
                    ConnectionResetError,
                    ConnectionAbortedError,
                    TimeoutError,
                    OSError,
                ):
                    close_client(client)

            for client in ready_write:
                if client not in clients:
                    continue

                try:
                    if client not in pending:
                        pending[client] = output_queues[client].get_nowait()

                    sent = client.send(pending[client])
                    if sent == 0:
                        close_client(client)
                    elif sent == len(pending[client]):
                        del pending[client]
                    else:
                        pending[client] = pending[client][sent:]
                except queue.Empty:
                    pending.pop(client, None)
                except (
                    BrokenPipeError,
                    ConnectionResetError,
                    ConnectionAbortedError,
                    TimeoutError,
                    OSError,
                ):
                    close_client(client)

        elapsed = (datetime.now() - start_time).total_seconds()
        return f"Server operated for {elapsed:.2f} seconds"

    except (ValueError, TypeError, OverflowError, OSError) as exc:
        elapsed = (datetime.now() - start_time).total_seconds()
        return f"Server failed after {elapsed:.2f} seconds: {exc}"

    finally:
        for client in list(clients):
            close_client(client)

        if server_socket is not None:
            try:
                server_socket.close()
            except OSError:
                pass

