import numpy as np
import pandas as pd
import matplotlib.pyplot as plt


def task_func(N=100, CATEGORIES=["A", "B", "C", "D", "E"], seed=42):
    if isinstance(N, bool) or not isinstance(N, (int, np.integer)):
        raise TypeError("N must be a non-negative integer")
    if N < 0:
        raise ValueError("N must be non-negative")

    categories = list(CATEGORIES)

    if len(set(categories)) != len(categories):
        raise ValueError("CATEGORIES must contain unique values")
    if N > 0 and not categories:
        raise ValueError("CATEGORIES must not be empty when N > 0")

    rng = np.random.default_rng(seed)

    x = rng.random(N)
    y = rng.random(N)

    if N < len(categories):
        category_values = rng.choice(categories, size=N, replace=False)
    elif N > 0:
        category_values = np.array(categories, dtype=object)
        remaining = N - len(categories)

        if remaining:
            extra = rng.choice(categories, size=remaining, replace=True)
            category_values = np.concatenate((category_values, extra))

        rng.shuffle(category_values)
    else:
        category_values = np.array([], dtype=object)

    df = pd.DataFrame(
        {
            "x": x,
            "y": y,
            "category": category_values,
        }
    )

    _, ax = plt.subplots()

    if N > 0:
        colors = plt.cm.tab10(np.linspace(0, 1, max(len(categories), 1)))

        for index, category in enumerate(categories):
            subset = df[df["category"] == category]
            if not subset.empty:
                ax.scatter(
                    subset["x"],
                    subset["y"],
                    color=colors[index % len(colors)],
                    label=str(category),
                )

        ax.legend()

    ax.set_xlabel("x")
    ax.set_ylabel("y")

    return df, ax

