def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):

    if isinstance(start_year, bool) or isinstance(end_year, bool):
        raise TypeError("Years must be integers.")
    if not isinstance(start_year, int) or not isinstance(end_year, int):
        raise TypeError("Years must be integers.")
    if not 0 <= start_year <= end_year <= 9999:
        raise ValueError("Years must be between 0 and 9999.")

    if not isinstance(email_domain, str) or not email_domain.strip():
        raise ValueError("email_domain must be a non-empty string.")
    if "@" in email_domain or any(char.isspace() for char in email_domain):
        raise ValueError("email_domain must not contain '@' or whitespace.")

    def fix_encoding(name):
        if not isinstance(name, str):
            name = str(name)

        if any(marker in name for marker in ("Ã", "Â", "â", "ð", "�")):
            try:
                return codecs.decode(name.encode("latin1"), "utf-8")
            except (UnicodeEncodeError, UnicodeDecodeError):
                pass

        return name

    try:
        names = [
            fix_encoding(name)
            for name in list(latin_names) + list(other_names)
        ]
    except TypeError as exc:
        raise TypeError("Name lists must be iterable.") from exc

    if not names:
        raise ValueError("At least one name must be provided.")

    rng = np.random.default_rng(rng_seed)
    records = []

    for record_id in range(1, 101):
        name = names[int(rng.integers(0, len(names)))]
        year = int(rng.integers(start_year, end_year + 1))
        month = int(rng.integers(1, 13))

        leap_year = year % 4 == 0 and (
            year % 100 != 0 or year % 400 == 0
        )
        days_in_month = [
            31, 29 if leap_year else 28, 31, 30, 31, 30,
            31, 31, 30, 31, 30, 31
        ][month - 1]
        day = int(rng.integers(1, days_in_month + 1))

        date_of_birth = f"{year:04d}-{month:02d}-{day:02d} 00:00:00"
        email = f"{name.lower()}{year}@{email_domain}"

        records.append({
            "ID": record_id,
            "Name": name,
            "Date of Birth": date_of_birth,
            "Email": email,
        })

    return pd.DataFrame(
        records,
        columns=["ID", "Name", "Date of Birth", "Email"]
    )

