import re
import urllib.parse
import ssl
import socket
import time


def task_func(myString):
    if not isinstance(myString, str):
        return {}

    result = {}
    urls = re.findall(r"https?://[^\s<>'\"]+", myString, flags=re.IGNORECASE)
    context = ssl.create_default_context()

    for raw_url in urls:
        url = raw_url.rstrip(".,;!?)]}")

        try:
            parsed = urllib.parse.urlparse(url)

            if parsed.scheme.lower() != "https" or not parsed.hostname:
                continue

            hostname = parsed.hostname.lower()
            port = parsed.port or 443

            with socket.create_connection((hostname, port), timeout=10) as sock:
                with context.wrap_socket(
                    sock,
                    server_hostname=hostname,
                ) as secure_sock:
                    certificate = secure_sock.getpeercert()
                    expiration = certificate.get("notAfter")

                    if not expiration:
                        continue

                    timestamp = ssl.cert_time_to_seconds(expiration)
                    result[hostname] = time.strftime(
                        "%Y-%m-%dT%H:%M:%SZ",
                        time.gmtime(timestamp),
                    )

        except (ssl.SSLError, OSError, ValueError, TypeError, KeyError):
            continue

    return result

