import csv
import collections


def task_func(csv_file, emp_prefix='EMP$$'):
    counts = collections.Counter()
    source = csv_file if hasattr(csv_file, 'read') else open(
        csv_file, 'r', newline='', encoding='utf-8'
    )

    try:
        reader = csv.reader(source)
        employee_column = 0
        first_row = True

        for row in reader:
            if not row or not any(cell.strip() for cell in row):
                continue

            if first_row:
                headers = [
                    cell.strip().lstrip('\ufeff').lower().replace(' ', '_')
                    for cell in row
                ]
                header_names = {
                    'employee',
                    'employee_id',
                    'employeeid',
                    'employee_name',
                }
                matching_columns = [
                    index for index, header in enumerate(headers)
                    if header in header_names
                ]
                if matching_columns:
                    employee_column = matching_columns[0]
                    first_row = False
                    continue
                first_row = False

            if employee_column >= len(row):
                continue

            employee = row[employee_column].strip()
            if employee and employee.startswith(emp_prefix):
                counts[employee] += 1

    finally:
        if source is not csv_file:
            source.close()

    return dict(counts)

