from sklearn.linear_model import LinearRegression
import math

DATA = {
    "Area_String": ["1,000", "2,000", "3,000", "4,000", "5,000"],
    "Price": [100, 200, 300, 400, 500],
}


def task_func(area_string, data=DATA):
    def parse_area(value):
        if isinstance(value, bool) or not pd.api.types.is_scalar(value):
            raise ValueError("Area must be a single non-negative numeric value.")
        if pd.isna(value):
            raise ValueError("Area cannot be missing.")

        text = str(value).strip().replace(",", "")
        parsed = pd.to_numeric(text, errors="coerce")

        if pd.isna(parsed) or not pd.api.types.is_number(parsed):
            raise ValueError(f"Invalid area value: {value!r}")

        parsed = float(parsed)
        if not math.isfinite(parsed):
            raise ValueError(f"Invalid area value: {value!r}")
        if parsed < 0:
            raise ValueError("Area must be non-negative.")

        return parsed

    frame = pd.DataFrame(data)
    required_columns = {"Area_String", "Price"}
    missing_columns = required_columns - set(frame.columns)

    if missing_columns:
        raise ValueError(
            f"Missing required columns: {', '.join(sorted(missing_columns))}"
        )
    if len(frame) < 2:
        raise ValueError("At least two training rows are required.")

    areas = frame["Area_String"].map(parse_area).astype(float)
    prices = pd.to_numeric(frame["Price"], errors="coerce")

    if prices.isna().any() or not prices.map(math.isfinite).all():
        raise ValueError("Price values must be finite numeric values.")

    model = LinearRegression()
    model.fit(areas.to_numpy().reshape(-1, 1), prices.to_numpy())

    return float(model.predict([[parse_area(area_string)]])[0])

