    for source_path in paths:
        filename = os.path.basename(source_path)

        if filename in (".", ".."):
            continue

        if not os.path.isfile(source_path):
            continue

        if os.path.splitext(filename)[1].lower() not in extensions:
            continue

        destination_path = os.path.join(destination_dir, filename)

        if os.path.isdir(destination_path):
            warnings.warn(
                f"Destination path is a directory: {destination_path}",
                RuntimeWarning,
            )
            continue

        try:
            with open(source_path, "rb"):
                pass
        except OSError as exc:
            warnings.warn(
                f"Could not read source file {source_path!r}: {exc}",
                RuntimeWarning,
            )
            continue

        try:
            shutil.copy2(source_path, destination_path)
        except (OSError, shutil.Error) as exc:
            warnings.warn(
                f"Could not transfer {source_path!r} to "
                f"{destination_path!r}: {exc}",
                RuntimeWarning,
            )
            continue

        transferred_files.append(filename)

    return transferred_files

