    for dataframe in df_list[1:]:
        if len(set(columns)) == len(columns):
            common_rows = (
                common_rows.merge(
                    dataframe.drop_duplicates(),
                    on=columns,
                    how="inner",
                )
                .drop_duplicates()
                .reset_index(drop=True)
            )
