import re
import os
from pathlib import Path
import csv


def task_func(directory: str, pattern: str = r'^(.*?)-\d+\.csv$') -> list:
    directory_path = Path(directory)

    if not directory_path.exists():
        raise FileNotFoundError(f"Directory does not exist: {directory}")
    if not directory_path.is_dir():
        raise NotADirectoryError(f"Not a directory: {directory}")

    try:
        matcher = re.compile(pattern)
    except re.error as exc:
        raise ValueError(f"Invalid regular expression: {pattern}") from exc

    new_files = []
    source_paths = sorted(
        (
            path
            for path in directory_path.iterdir()
            if path.is_file() and path.suffix.lower() == ".csv"
        ),
        key=lambda path: path.name,
    )

    for source_path in source_paths:
        match = matcher.match(source_path.name)
        if match is None:
            continue

        if match.lastindex is None:
            raise ValueError(
                "The pattern must contain a capture group for the destination name."
            )

        base_name = match.group(1)
        if base_name is None or not base_name:
            raise ValueError("The destination filename cannot be empty.")

        destination_name = f"{base_name}.csv"
        destination_path = directory_path / destination_name

        if destination_path == source_path or destination_path.exists():
            continue

        destination_path.write_bytes(source_path.read_bytes())
        new_files.append(destination_name)

    return new_files

