import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if pattern == "":
        return df.copy()

    regex = re.compile(pattern)

    def reorder_matching_words(value):
        if not isinstance(value, str):
            return value

        words = value.split()
        matching_words = [
            word for word in words if regex.fullmatch(word)
        ][::-1]

        matching_index = 0
        reordered_words = []

        for word in words:
            if regex.fullmatch(word):
                reordered_words.append(matching_words[matching_index])
                matching_index += 1
            else:
                reordered_words.append(word)

        return " ".join(reordered_words)

    result = df.copy()
    result[column_name] = result[column_name].apply(reorder_matching_words)
    return result

