import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str},
        },
        "required": ["name", "age", "email"],
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$",
):
    try:
        if not isinstance(file_path, (str, bytes, os.PathLike)):
            raise ValueError("Invalid file path")
        if not os.path.isfile(file_path):
            raise ValueError("File does not exist or is not a regular file")

        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as exc:
        if isinstance(exc, ValueError) and str(exc).startswith(
            ("Missing", "Invalid", "Attribute")
        ):
            raise
        raise ValueError("Unable to read or parse JSON file") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object")

    if not isinstance(INPUT_JSON, dict):
        raise ValueError("Invalid schema")

    properties = INPUT_JSON.get("properties")
    required = INPUT_JSON.get("required")

    if not isinstance(properties, dict) or not isinstance(required, list):
        raise ValueError("Invalid schema")

    for field in required:
        if not isinstance(field, str) or field not in properties:
            raise ValueError(f"Invalid schema definition for: {field}")
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")

    for field, definition in properties.items():
        if field not in data:
            continue
        if not isinstance(definition, dict) or "type" not in definition:
            raise ValueError(f"Invalid schema definition for: {field}")

        expected_type = definition["type"]
        value = data[field]

        if expected_type is int and isinstance(value, bool):
            raise ValueError(f"Invalid type for attribute: {field}")

        try:
            valid_type = isinstance(value, expected_type)
        except TypeError as exc:
            raise ValueError(f"Invalid schema type for: {field}") from exc

        if not valid_type:
            raise ValueError(f"Invalid type for attribute: {field}")

    if "email" in data:
        if not isinstance(data["email"], str):
            raise ValueError("Email must be a string")
        try:
            pattern = re.compile(EMAIL_REGEX)
            if pattern.fullmatch(data["email"]) is None:
                raise ValueError("Invalid email format")
        except (re.error, TypeError) as exc:
            raise ValueError("Invalid email regular expression") from exc

    try:
        if attribute not in data:
            raise ValueError(f"Attribute not found: {attribute}")
    except TypeError as exc:
        raise ValueError("Invalid attribute") from exc

    return data[attribute]

