import ssl
import os
import hashlib


def task_func(client_socket, cert_file, key_file, buffer_size=1024):
    secure_socket = None

    try:
        if buffer_size <= 0:
            raise ValueError("buffer_size must be greater than zero")

        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.load_cert_chain(certfile=cert_file, keyfile=key_file)

        secure_socket = context.wrap_socket(client_socket, server_side=True)

        request_data = bytearray()
        while True:
            chunk = secure_socket.recv(buffer_size)
            if not chunk:
                break

            request_data.extend(chunk)

            if len(chunk) < buffer_size:
                break

        file_path = request_data.decode("utf-8").strip()

        if not os.path.isfile(file_path):
            response = "File not found"
        else:
            digest = hashlib.sha256()
            with open(file_path, "rb") as file:
                while True:
                    chunk = file.read(buffer_size)
                    if not chunk:
                        break
                    digest.update(chunk)

            response = digest.hexdigest()

        secure_socket.sendall(response.encode("utf-8"))
        return response

    except Exception as exc:
        error_message = f"Error: {exc}"

        if secure_socket is not None:
            try:
                secure_socket.sendall(error_message.encode("utf-8"))
            except Exception:
                pass

        return error_message

