from random import shuffle, randint
import pandas as pd


def task_func(l, n_groups=5):
    """Return a shuffled, twice-length Series of cyclically rotated strings.

    The input is copied before shuffling. The output contains two cycles of the
    shuffled input. For each value, a random prefix length from 0 through
    n_groups is moved to the end. Elements must be strings.
    """
    if not isinstance(n_groups, int):
        raise TypeError("n_groups must be an integer")
    if n_groups < 0:
        raise ValueError("n_groups must be non-negative")

    values = list(l)
    if not values:
        return pd.Series(dtype=object)

    if any(not isinstance(value, str) for value in values):
        raise TypeError("All elements of l must be strings")

    shuffle(values)

    result = []
    for index in range(len(values) * 2):
        value = values[index % len(values)]
        count = randint(0, n_groups)
        result.append(value[count:] + value[:count])

    return pd.Series(result)

