import pandas as pd
import folium
from geopy.geocoders import Photon


def task_func(dic):
    geolocator = Photon(user_agent="geoapiExercises")

    def is_missing(value):
        if value is None:
            return True
        if isinstance(value, str):
            return not value.strip()
        try:
            missing = pd.isna(value)
            return bool(missing) if not hasattr(missing, "__len__") else False
        except Exception:
            return False

    def normalize_records(data):
        if isinstance(data, pd.DataFrame):
            return data.to_dict(orient="records")

        if isinstance(data, dict):
            if "locations" in data:
                locations = data["locations"]
                if isinstance(locations, pd.DataFrame):
                    return locations.to_dict(orient="records")
                if isinstance(locations, (list, tuple)):
                    return list(locations)
                if isinstance(locations, dict):
                    return [
                        dict(value, name=key)
                        if isinstance(value, dict)
                        else {"name": key, "location": value}
                        for key, value in locations.items()
                    ]

            location_keys = {
                "latitude", "longitude", "lat", "lon", "lng",
                "name", "address", "location", "query"
            }
            if any(key in data for key in location_keys):
                try:
                    return pd.DataFrame(data).to_dict(orient="records")
                except (TypeError, ValueError):
                    return [data]

            return [
                {"name": key, "location": value}
                for key, value in data.items()
            ]

        if isinstance(data, (list, tuple)):
            return list(data)

        if isinstance(data, str):
            return [{"address": data}]

        return []

    def get_value(record, *keys):
        for key in keys:
            if key in record and not is_missing(record[key]):
                return record[key]
        return None

    valid_locations = []

    for item in normalize_records(dic):
        record = item if isinstance(item, dict) else {"location": item}

        latitude = get_value(record, "latitude", "lat")
        longitude = get_value(record, "longitude", "lon", "lng")

        if is_missing(latitude) or is_missing(longitude):
            location_value = get_value(record, "location", "address", "query")

            if not isinstance(location_value, str):
                try:
                    if len(location_value) >= 2:
                        latitude, longitude = location_value[0], location_value[1]
                except (TypeError, IndexError):
                    pass

            if is_missing(latitude) or is_missing(longitude):
                if isinstance(location_value, str):
                    try:
                        resolved = geolocator.geocode(location_value)
                        if resolved is not None:
                            latitude = resolved.latitude
                            longitude = resolved.longitude
                    except Exception:
                        pass

        try:
            latitude = float(latitude)
            longitude = float(longitude)
        except (TypeError, ValueError):
            continue

        if not (-90 <= latitude <= 90 and -180 <= longitude <= 180):
            continue

        label = get_value(record, "name", "address", "location")
        if is_missing(label):
            label = f"{latitude}, {longitude}"

        valid_locations.append((latitude, longitude, str(label)))

    if valid_locations:
        center = [
            sum(latitude for latitude, _, _ in valid_locations)
            / len(valid_locations),
            sum(longitude for _, longitude, _ in valid_locations)
            / len(valid_locations),
        ]
    else:
        center = [0, 0]

    result_map = folium.Map(location=center, zoom_start=2)

    for latitude, longitude, label in valid_locations:
        folium.Marker(
            location=[latitude, longitude],
            popup=label,
        ).add_to(result_map)

    return result_map

