import matplotlib.pyplot as plt
from scipy.stats import norm


def task_func(n_samples=1000, mu=0, sigma=1, random_seed=0):
    if isinstance(n_samples, (bool, np.bool_)) or not isinstance(
        n_samples, (int, np.integer)
    ):
        raise TypeError("n_samples must be a positive integer")
    if n_samples <= 0:
        raise ValueError("n_samples must be positive")

    try:
        mu = float(mu)
    except (TypeError, ValueError):
        raise TypeError("mu must be numeric") from None

    try:
        sigma = float(sigma)
    except (TypeError, ValueError):
        raise TypeError("sigma must be numeric") from None

    if not np.isfinite(mu):
        raise ValueError("mu must be finite")
    if not np.isfinite(sigma) or sigma <= 0:
        raise ValueError("sigma must be positive and finite")

    rng = np.random.default_rng(random_seed)
    samples = rng.normal(loc=mu, scale=sigma, size=n_samples)

    _, ax = plt.subplots()
    ax.hist(samples, bins=30, density=True)

    sample_min = float(samples.min())
    sample_max = float(samples.max())
    if sample_min == sample_max:
        x_min = mu - 4 * sigma
        x_max = mu + 4 * sigma
    else:
        padding = 0.05 * (sample_max - sample_min)
        x_min = sample_min - padding
        x_max = sample_max + padding

    x = np.linspace(x_min, x_max, 200)
    ax.plot(
        x,
        norm.pdf(x, loc=mu, scale=sigma),
        color="red",
        linewidth=2,
    )

    return ax, samples

