import cgi
import http.server
import smtplib
from email.mime.text import MIMEText
import json


def task_func(smtp_server, smtp_port, smtp_username, smtp_password):
    class EmailRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, status, message, reason=None):
            body = json.dumps({"message": message}).encode("utf-8")
            self.send_response(status, reason)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            try:
                content_length = self.headers.get("Content-Length")
                if content_length is None:
                    raise ValueError("Missing Content-Length")

                length = int(content_length)
                if length < 0:
                    raise ValueError("Invalid Content-Length")

                data = json.loads(self.rfile.read(length).decode("utf-8"))

                if not isinstance(data, dict):
                    raise ValueError("Email data must be a JSON object")

                for key in ("subject", "message", "to"):
                    if key not in data:
                        raise ValueError(f"Missing required key: {key}")

                subject = str(data["subject"])
                message = str(data["message"])
                recipient = str(data["to"])

                email = MIMEText(message)
                email["Subject"] = subject
                email["From"] = smtp_username
                email["To"] = recipient

                smtp = None
                try:
                    smtp = smtplib.SMTP(smtp_server, smtp_port)
                    smtp.login(smtp_username, smtp_password)
                    smtp.sendmail(
                        smtp_username,
                        [recipient],
                        email.as_string(),
                    )
                finally:
                    if smtp is not None:
                        try:
                            smtp.quit()
                        except Exception:
                            pass

                self._send_response(200, "Email sent successfully", "OK")

            except smtplib.SMTPAuthenticationError:
                self._send_response(
                    535,
                    "Authentication Failed",
                    "Authentication Failed",
                )
            except (json.JSONDecodeError, UnicodeDecodeError, ValueError, TypeError):
                self._send_response(400, "Bad Request", "Bad Request")

    return EmailRequestHandler

