import requests
from pathlib import Path
import zipfile
import shutil

# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")


def task_func(url, filename):
    try:
        if filename is None:
            raise ValueError("Invalid filename")

        filename = str(filename)
        archive_name = Path(filename)

        if (
            not filename
            or archive_name.is_absolute()
            or ".." in archive_name.parts
            or archive_name.name in {"", ".", ".."}
        ):
            raise ValueError("Invalid filename")

        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        archive_path = DOWNLOAD_DIR / archive_name
        archive_path.parent.mkdir(parents=True, exist_ok=True)

        response = requests.get(url, timeout=30)
        response.raise_for_status()

        with archive_path.open("wb") as file:
            file.write(response.content)

        if ZIP_DIR.exists():
            if ZIP_DIR.is_dir():
                shutil.rmtree(ZIP_DIR)
            else:
                ZIP_DIR.unlink()

        ZIP_DIR.mkdir(parents=True, exist_ok=True)
        extraction_root = ZIP_DIR.resolve()

        with zipfile.ZipFile(archive_path, "r") as archive:
            for member in archive.infolist():
                target = (ZIP_DIR / member.filename).resolve()
                try:
                    target.relative_to(extraction_root)
                except ValueError as error:
                    raise ValueError("Unsafe ZIP path") from error

            archive.extractall(ZIP_DIR)

        filenames = sorted(
            path.relative_to(ZIP_DIR).as_posix()
            for path in ZIP_DIR.rglob("*")
            if path.is_file()
        )

        return ("Download and extraction successful", filenames)

    except requests.exceptions.RequestException as error:
        return (f"Error downloading file: {error}", [])
    except (OSError, zipfile.BadZipFile, zipfile.LargeZipFile,
            ValueError, TypeError, RuntimeError) as error:
        return (f"Error handling file: {error}", [])

