import pandas as pd
from datetime import datetime
import matplotlib.pyplot as plt

# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    if not isinstance(date_str, str):
        raise ValueError("date_str must be in yyyy-mm-dd format")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("date_str must be in yyyy-mm-dd format") from exc

    if requested_date.strftime("%Y-%m-%d") != date_str:
        raise ValueError("date_str must be in yyyy-mm-dd format")

    if requested_date < datetime.now().date():
        raise ValueError("date_str cannot refer to a past date")

    booked_rooms = set()

    if booking_data is not None:
        if isinstance(booking_data, pd.DataFrame):
            records = booking_data.to_dict("records")
        elif isinstance(booking_data, dict):
            records = [booking_data]
        else:
            try:
                records = iter(booking_data)
            except TypeError:
                records = ()

        for booking in records:
            if not isinstance(booking, dict):
                continue

            room = booking.get("room", booking.get("Room"))
            booking_date = booking.get(
                "date",
                booking.get("booking_date", booking.get("Date")),
            )

            if room not in ROOMS:
                continue

            if isinstance(booking_date, datetime):
                booking_date = booking_date.strftime("%Y-%m-%d")
            elif hasattr(booking_date, "strftime"):
                try:
                    booking_date = booking_date.strftime("%Y-%m-%d")
                except (AttributeError, ValueError, TypeError):
                    continue

            if booking_date == date_str:
                booked_rooms.add(room)

    report = pd.DataFrame({
        "Room": ROOMS,
        "Status": [
            "Booked" if room in booked_rooms else "Available"
            for room in ROOMS
        ],
    })

    values = [1 if status == "Booked" else 0 for status in report["Status"]]

    _, ax = plt.subplots()
    ax.bar(report["Room"], values)
    ax.set_title(f"Room Booking Status for {date_str}")
    ax.set_xlabel("Room")
    ax.set_ylabel("Booking Status")
    ax.set_yticks([0, 1])
    ax.set_yticklabels(["Available", "Booked"])

    return report, ax

