import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from decimal import Decimal, InvalidOperation


def task_func(data_str, separator=",", bins=20):
    if not isinstance(data_str, str) or not isinstance(separator, str):
        raise ValueError("data_str and separator must be strings")

    if not separator or not data_str.strip():
        raise ValueError("data must not be empty")

    values = data_str.split(separator)

    if any(not value.strip() for value in values):
        raise ValueError("data contains empty values")

    converted = []
    int64_info = np.iinfo(np.int64)

    try:
        for value in values:
            number = Decimal(value.strip())

            if not number.is_finite() or number != number.to_integral_value():
                raise ValueError("values must be integers")

            integer = int(number)
            if integer < int64_info.min or integer > int64_info.max:
                raise ValueError("value is outside int64 range")

            converted.append(integer)
    except (InvalidOperation, ValueError, OverflowError, TypeError):
        raise ValueError("failed to convert data to int64")

    series = pd.Series(converted, dtype="int64")

    _, axes = plt.subplots()
    axes.hist(series, bins=bins, rwidth=0.9, color="#607c8e")
    axes.grid(True)

    return series, axes

