                    if result:
                        return result
            elif isinstance(value, (list, tuple)):
                for item in value:
                    result = find_ip(item)
                    if result:
                        return result
            elif isinstance(value, str):
                pattern = rf"(?<![\d.]){IP_REGEX}(?![\d.])"
                for candidate in re.findall(pattern, value):
                    if all(0 <= int(part) <= 255 for part in candidate.split(".")):
                        return candidate
            return None

        ip_address = find_ip(data)
        if ip_address:
            return ip_address

        return "Error: No valid IPv4 address found in the API response."
