from itertools import combinations
from random import sample


def task_func(df, tuples, n_plots):
    import numbers

    import matplotlib.pyplot as plt
    import pandas as pd

    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if (
        isinstance(n_plots, bool)
        or not isinstance(n_plots, numbers.Integral)
        or n_plots < 0
    ):
        raise ValueError("n_plots must be a non-negative integer")

    columns = list(df.columns)
    rows_to_remove = [False] * len(df)

    try:
        tuple_values = iter(tuples)
    except TypeError as exc:
        raise TypeError("tuples must be an iterable of row-value tuples") from exc

    for values in tuple_values:
        try:
            values = tuple(values)
        except TypeError as exc:
            raise TypeError("Each item in tuples must be iterable") from exc

        if len(values) != len(columns):
            raise ValueError(
                "Each tuple must have the same length as the number of DataFrame columns"
            )

        row_matches = [True] * len(df)

        for column, value in zip(columns, values):
            missing_value = pd.isna(value)
            if not isinstance(missing_value, bool):
                raise TypeError("Tuple values must be scalar values")

            if missing_value:
                matches = df[column].isna().tolist()
            else:
                matches = df[column].eq(value).fillna(False).tolist()

            row_matches = [
                current and match
                for current, match in zip(row_matches, matches)
            ]

        rows_to_remove = [
            current or match
            for current, match in zip(rows_to_remove, row_matches)
        ]

    remaining_df = df.loc[
        [not should_remove for should_remove in rows_to_remove]
    ].copy()

    if remaining_df.empty or len(columns) < 2 or n_plots == 0:
        return remaining_df, []

    pairs = list(combinations(columns, 2))
    selected_pairs = (
        pairs if n_plots >= len(pairs) else sample(pairs, int(n_plots))
    )

    plots = []
    for x_column, y_column in selected_pairs:
        _, ax = plt.subplots()
        ax.scatter(remaining_df[x_column], remaining_df[y_column])
        ax.set_xlabel(str(x_column))
        ax.set_ylabel(str(y_column))
        plots.append(((x_column, y_column), ax))

    return remaining_df, plots

