                encoder = LabelEncoder()
                encoded = encoder.fit_transform(series.loc[non_null])
                result[column] = series.astype(object)
                result.loc[non_null, column] = encoded

        elif pd.api.types.is_numeric_dtype(series):
            mean = series.mean()
            std = series.std()

            if pd.isna(std) or std == 0:
                result[column] = series.where(series.isna(), 0)
            else:
                result[column] = (series - mean) / std

    return result

