import pandas as pd
import os
import json
from collections import Counter
import re


def task_func(json_dir_path, word_count):
    if isinstance(word_count, bool) or not isinstance(word_count, int):
        raise ValueError("word_count must be a non-negative integer")
    if word_count < 0:
        raise ValueError("word_count must be a non-negative integer")
    if word_count == 0:
        return []

    try:
        if not os.path.isdir(json_dir_path):
            return []
        filenames = sorted(os.listdir(json_dir_path))
    except (OSError, TypeError):
        return []

    word_pattern = re.compile(r"[^\W_]+", re.UNICODE)
    word_counter = Counter()

    def extract_strings(value):
        if isinstance(value, str):
            yield value
        elif isinstance(value, dict):
            for nested_value in value.values():
                yield from extract_strings(nested_value)
        elif isinstance(value, list):
            for nested_value in value:
                yield from extract_strings(nested_value)

    for filename in filenames:
        if not isinstance(filename, str) or not filename.lower().endswith(".json"):
            continue

        file_path = os.path.join(json_dir_path, filename)
        if not os.path.isfile(file_path):
            continue

        try:
            with open(file_path, "r", encoding="utf-8") as file:
                data = json.load(file)
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue

        for text in extract_strings(data):
            word_counter.update(word_pattern.findall(text.lower()))

    return word_counter.most_common(word_count)

