import pandas as pd
from scipy.stats import pearsonr


def task_func(data):
    if len(data) < 2:
        return float("nan")

    score_column = "score" if "score" in data.columns else "scores"
    grade_column = "grade" if "grade" in data.columns else "grades"

    scores = pd.to_numeric(data[score_column], errors="coerce")
    grades = data[grade_column]

    if isinstance(grades.dtype, pd.CategoricalDtype):
        categories = list(grades.cat.categories)
    else:
        standard_order = ["F", "E", "D", "C", "B", "A"]
        values = grades.dropna().unique()
        string_values = {str(value) for value in values}

        if string_values and string_values.issubset(set(standard_order)):
            categories = [
                grade for grade in standard_order if grade in string_values
            ]
        else:
            categories = sorted(values, key=str)

    encoded = pd.Series(
        pd.Categorical(grades, categories=categories, ordered=True).codes,
        index=data.index,
        dtype="float64",
    ).replace(-1, float("nan"))

    valid = scores.notna() & encoded.notna()
    scores = scores[valid]
    encoded = encoded[valid]

    if len(scores) < 2 or scores.nunique() < 2 or encoded.nunique() < 2:
        return float("nan")

    correlation, _ = pearsonr(scores.to_numpy(), encoded.to_numpy())
    return float(correlation)

