import re
import os
import glob
from pathlib import Path


def task_func(pattern, directory, extensions):
    regex = re.compile(pattern, re.IGNORECASE)

    directory = os.fspath(directory)
    if not os.path.exists(directory):
        raise FileNotFoundError(directory)
    if not os.path.isdir(directory):
        raise NotADirectoryError(directory)

    if extensions is None:
        allowed_extensions = None
    else:
        if isinstance(extensions, (str, os.PathLike)):
            extensions = [extensions]

        allowed_extensions = set()
        for extension in extensions:
            extension = str(extension).lower()
            if extension:
                allowed_extensions.add(
                    extension if extension.startswith(".") else f".{extension}"
                )

        if not allowed_extensions:
            allowed_extensions = None

    matches = []
    seen_real_paths = set()

    for root, dirs, files in os.walk(directory, followlinks=False):
        dirs[:] = [
            name
            for name in dirs
            if not os.path.islink(os.path.join(root, name))
        ]

        for filename in files:
            path = os.path.abspath(os.path.join(root, filename))

            if (
                allowed_extensions is not None
                and os.path.splitext(filename)[1].lower() not in allowed_extensions
            ):
                continue

            real_path = os.path.realpath(path)
            if real_path in seen_real_paths:
                continue

            try:
                with open(path, "r", encoding="utf-8", errors="ignore") as file:
                    contents = file.read()
            except OSError:
                continue

            seen_real_paths.add(real_path)

            if regex.search(contents):
                matches.append(path)

    return {"list": sorted(matches)}

