# Constants
COLUMNS = ['A', 'B', 'C', 'D', 'E']


def task_func(df: pd.DataFrame, tuples: list, n_plots: int) -> (pd.DataFrame, list):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    missing_columns = [column for column in COLUMNS if column not in df.columns]
    if missing_columns:
        raise ValueError(f"Missing required columns: {missing_columns}")

    if not isinstance(tuples, list):
        raise TypeError("tuples must be a list")

    if isinstance(n_plots, bool) or not isinstance(n_plots, int):
        raise TypeError("n_plots must be an integer")
    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    remove_mask = pd.Series(False, index=range(len(df)))

    for values in tuples:
        if not isinstance(values, (tuple, list)) or len(values) != len(COLUMNS):
            raise ValueError(
                f"Each item in tuples must contain exactly {len(COLUMNS)} values"
            )

        match = pd.Series(True, index=range(len(df)))

        for column, value in zip(COLUMNS, values):
            missing = pd.isna(value)
            if not isinstance(missing, bool):
                try:
                    missing = bool(missing)
                except (TypeError, ValueError) as exc:
                    raise ValueError("Tuple values must be scalar values") from exc

            column_values = df[column].reset_index(drop=True)

            if missing:
                condition = column_values.isna()
            else:
                condition = column_values.eq(value).fillna(False)

            match &= condition

        remove_mask |= match

    filtered_df = df.iloc[~remove_mask.to_numpy()].copy()

    if filtered_df.empty:
        return filtered_df, []

    plots = []
    for _ in range(n_plots):
        x_column, y_column = sample(COLUMNS, 2)
        plots.append(
            sns.jointplot(
                data=filtered_df,
                x=x_column,
                y=y_column,
            )
        )

    return filtered_df, plots

