import numpy as np
from scipy import integrate
import matplotlib.pyplot as plt


def task_func(func, x_range=(-2, 2), num_points=1000):
    if not callable(func):
        raise TypeError("func must be callable")

    try:
        if len(x_range) != 2:
            raise ValueError("x_range must contain exactly two bounds")
        start, end = (float(value) for value in x_range)
    except TypeError as exc:
        raise TypeError("x_range must contain exactly two numeric bounds") from exc
    except ValueError as exc:
        raise ValueError("x_range must contain exactly two numeric bounds") from exc

    if not np.isfinite([start, end]).all():
        raise ValueError("x_range bounds must be finite")

    if isinstance(num_points, bool) or not isinstance(
        num_points, (int, np.integer)
    ):
        raise TypeError("num_points must be an integer")
    if num_points < 2:
        raise ValueError("num_points must be at least 2")

    name = getattr(func, "__name__", func.__class__.__name__)
    x = np.linspace(start, end, num_points)

    try:
        y = np.asarray(func(x), dtype=float)
    except Exception:
        y = np.asarray([func(value) for value in x], dtype=float)

    if y.ndim == 0:
        y = np.full(x.shape, y.item(), dtype=float)
    elif y.shape != x.shape:
        raise ValueError("func must return one value for each x-value")

    if not np.isfinite(y).all():
        raise ValueError("func returned non-finite values")

    cumulative_integral = integrate.cumulative_trapezoid(y, x, initial=0)

    _, ax = plt.subplots()
    ax.plot(x, y, label=f"{name}(x)")
    ax.plot(
        x,
        cumulative_integral,
        label=f"Cumulative integral of {name}(x)",
    )
    ax.set_xlabel(f"x ({name})")
    ax.set_ylabel(f"{name}(x) and cumulative integral")
    ax.legend()

    return ax

