import subprocess
import time
import threading


def task_func(file_list):
    processes = []
    exit_codes = [None] * len(file_list)

    try:
        for file_path in file_list:
            processes.append(subprocess.Popen([file_path]))
    except OSError:
        for process in processes:
            process.terminate()
        for process in processes:
            process.wait()
        raise

    def wait_for_process(index, process):
        exit_codes[index] = process.wait()

    threads = [
        threading.Thread(target=wait_for_process, args=(index, process))
        for index, process in enumerate(processes)
    ]

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    return exit_codes

