import sqlite3
import pandas as pd
import csv
from io import StringIO
import os

# Constants
DATABASE_NAME = 'test.db'
TABLE_NAME = 'test_table'


def task_func(csv_input):
    def quote_identifier(identifier):
        return '"' + identifier.replace('"', '""') + '"'

    file_handle = None

    try:
        if isinstance(csv_input, (str, os.PathLike)):
            file_handle = open(csv_input, "r", encoding="utf-8", newline="")
            content = file_handle.read()
        elif hasattr(csv_input, "read"):
            content = csv_input.read()
        else:
            raise TypeError(
                "csv_input must be a file path or a file-like object"
            )

        if not isinstance(content, str):
            raise TypeError("CSV input must contain text data")

        rows = list(csv.reader(StringIO(content, newline=""), strict=True))

        if not rows:
            raise ValueError("CSV input is empty")

        headers = rows[0]

        if any(not header.strip() for header in headers):
            raise ValueError("CSV headers must not be empty")

        normalized_headers = [header.casefold() for header in headers]
        if len(normalized_headers) != len(set(normalized_headers)):
            raise ValueError("CSV headers must be unique")

        for row_number, row in enumerate(rows[1:], start=2):
            if len(row) != len(headers):
                raise ValueError(
                    f"Row {row_number} has {len(row)} fields; "
                    f"expected {len(headers)}"
                )

        quoted_table = quote_identifier(TABLE_NAME)
        quoted_headers = [quote_identifier(header) for header in headers]

        connection = sqlite3.connect(DATABASE_NAME)
        try:
            connection.execute("BEGIN")
            connection.execute(f"DROP TABLE IF EXISTS {quoted_table}")

            columns_sql = ", ".join(
                f"{header} TEXT" for header in quoted_headers
            )
            connection.execute(
                f"CREATE TABLE {quoted_table} ({columns_sql})"
            )

            placeholders = ", ".join("?" for _ in headers)
            insert_sql = (
                f"INSERT INTO {quoted_table} "
                f"({', '.join(quoted_headers)}) "
                f"VALUES ({placeholders})"
            )
            connection.executemany(insert_sql, rows[1:])
            connection.commit()

            return pd.read_sql_query(
                f"SELECT * FROM {quoted_table}",
                connection,
            )
        except Exception:
            connection.rollback()
            raise
        finally:
            connection.close()
    finally:
        if file_handle is not None:
            file_handle.close()

