from sklearn.preprocessing import MinMaxScaler


def task_func(df):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    required_columns = {"id", "Age", "Income"}
    missing_columns = required_columns - set(df.columns)
    if missing_columns:
        raise ValueError(f"Missing required columns: {sorted(missing_columns)}")

    scaled_df = df.copy()

    if scaled_df.empty:
        return scaled_df, (
            np.array([], dtype=int),
            np.array([], dtype=float),
        )

    positions = np.arange(len(scaled_df))
    id_values = pd.Series(scaled_df["id"].to_numpy(), index=positions)

    result_columns = {}

    for column in ("Age", "Income"):
        values = scaled_df[column].to_numpy(dtype=float, copy=True)

        for _, group_positions in id_values.groupby(
            id_values, sort=False, dropna=False
        ).groups.items():
            group_positions = np.asarray(group_positions, dtype=int)
            group_values = values[group_positions]
            valid = ~np.isnan(group_values)

            if valid.any():
                scaler = MinMaxScaler()
                values[group_positions[valid]] = scaler.fit_transform(
                    group_values[valid].reshape(-1, 1)
                ).ravel()

        result_columns[column] = values

    for column, values in result_columns.items():
        scaled_df[column] = values

    income_values = scaled_df["Income"].dropna().to_numpy(dtype=float)

    if income_values.size == 0:
        histogram_data = (
            np.array([], dtype=int),
            np.array([], dtype=float),
        )
    else:
        histogram_data = np.histogram(income_values, bins=10)

    return scaled_df, histogram_data

