import numpy as np
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import mean_squared_error


def task_func(num_samples=1000, k=5, d=2, random_seed=None):
    if not isinstance(num_samples, (int, np.integer)):
        raise TypeError("num_samples must be an integer")
    if num_samples <= 0:
        raise ValueError("num_samples must be positive")
    if not np.isfinite(k) or not np.isfinite(d):
        raise ValueError("k and d must be finite")

    rng = np.random.default_rng(random_seed)
    original_data = rng.normal(0, 1, num_samples)
    transformed_data = k * original_data + d

    standardized_data = StandardScaler().fit_transform(
        transformed_data.reshape(-1, 1)
    ).ravel()

    return float(mean_squared_error(transformed_data, standardized_data))

